/* Ruta de entrenamiento: materias, estaciones (fichas y pruebas) y la ruta del mapa.
   Lo exporta Escritorio\APP\Estaciones\_herramientas\exportar_app.js: no se edita a mano. */
window.ESTACIONES_DATA={"format":1,"generated":"2026-10-02","subjects":[{"id":"electrico","title":"Eléctrico","color":"#C98500","stations":[{"id":"ele-1","subject":"electrico","order":1,"kind":"lesson","level":1,"ident":"GEN","title":"Las fuentes de energía","goal":"Nombrar las fuentes de energía eléctrica del A320 y qué entrega cada una.","intro":"Partimos por el principio: de dónde sale la electricidad del avión. Cinco fichas y lo pruebas.","minutes":5,"cards":[{"id":"ele-1-c1","title":"AC y DC","body":"El avión usa dos tipos de energía eléctrica:\n- **AC**: corriente alterna trifásica de **115/200 V y 400 Hz**, siempre a la misma frecuencia.\n- **DC**: corriente continua de **28 V**.\n\nLos generadores producen AC, y una parte de esa AC se transforma en DC para los equipos que la necesitan.","keyIdea":"AC de 115/200 V y 400 Hz, y DC de 28 V que sale de transformar AC."},{"id":"ele-1-c2","title":"Tres generadores de 90 KVA","body":"Cada motor mueve un generador: son el **GEN 1** y el **GEN 2**, de hasta **90 KVA** cada uno.\n\nEl **APU GEN**, movido por el APU, entrega lo mismo y puede reemplazar a uno o a los dos generadores de motor en cualquier momento.\n\nEn tierra se suma el **external power** (EXT PWR), que se enchufa en una toma cerca de la rueda de nariz.","diagram":{"alt":"A320 visto desde abajo con cada fuente eléctrica: el IDG de cada motor (GEN 1 y GEN 2), el APU GEN en la cola, la toma del EXT PWR junto a la rueda de nariz, las dos baterías y el RAT, que con el Blue mueve el EMER GEN.","src":"assets/estaciones/diagramas/ele-fuentes-avion.svg"},"keyIdea":"GEN 1, GEN 2 y APU GEN: 90 KVA cada uno. En tierra, además, el EXT PWR."},{"id":"ele-1-c3","title":"Una sola fuente puede con todo","body":"El **APU GEN** o el **external power** pueden alimentar **toda la red**, no solo una parte.\n\nPor eso, en tierra, con el APU funcionando o con el EXT PWR conectado, el avión tiene todos sus sistemas eléctricos aunque los motores estén apagados.","keyIdea":"El APU GEN o el EXT PWR alimentan solos toda la red."},{"id":"ele-1-c4","title":"Los respaldos","body":"Si fallan todos los generadores principales, quedan tres respaldos:\n- el **emergency generator** (EMER GEN), de 5 KVA, movido por el hidráulico Blue;\n- el **static inverter** (STAT INV), que transforma la DC de la batería 1 en AC (1 KVA);\n- las **dos baterías**, de 23 Ah cada una.\n\nCada respaldo tiene su propia estación más adelante.","diagram":{"alt":"Esquema de la red eléctrica: abajo GEN 1, APU GEN, EXT PWR y GEN 2; arriba las barras AC y DC, las baterías y, en reserva, el ESS TR, el STAT INV y el EMER GEN.","src":"assets/estaciones/diagramas/ele-arquitectura.svg"},"keyIdea":"Respaldos: EMER GEN (Blue), static inverter (desde BAT 1) y dos baterías."},{"id":"ele-1-c5","title":"La DC y dónde mirar","body":"Los **TR** (Transformer Rectifier) transforman AC en DC. El **TR 1** y el **TR 2** alimentan la red DC, y un tercero igual, el **ESS TR**, queda para lo esencial.\n\n¿Qué fuente alimenta cada barra? Se ve en la **página ELEC del ECAM** (ELEC pb del ECAM control panel): cada generador, cada barra y cada TR, con sus valores.","diagram":{"alt":"Página ELEC del ECAM en vuelo normal: baterías arriba, barras DC, TR, barras AC y generadores abajo.","src":"assets/estaciones/diagramas/ele-ecam-normal.svg"},"keyIdea":"TR 1, TR 2 y ESS TR transforman AC en DC. Todo se ve en la página ELEC del ECAM."}],"test":[{"id":"ele-1-t1","type":"mcq","question":"THE ENGINE GENERATORS AND APU GENERATOR ARE RATED AT _______ KVA.","options":["50","90","45"],"correct":1,"explanation":"Los generadores de motor y el generador del APU están calificados a 90 kVA cada uno, el estándar de potencia del sistema eléctrico del A320.","taughtIn":["ele-1-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1qxmlmu"}},{"id":"ele-1-t2","type":"mcq","question":"¿Qué capacidad tienen el APU generator y el external power respecto de la red eléctrica?","options":["Solo pueden alimentar AC BUS 2","Pueden alimentar toda la red","Solo alimentan los buses esenciales","Solo cargan las baterías"],"correct":1,"explanation":"El APU GEN o el external power pueden alimentar solos toda la red, no solo una barra ni solo las barras esenciales.","taughtIn":["ele-1-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1kh3tll"}},{"id":"ele-1-t3","type":"mcq","question":"THE A-320 HAS _______ BATTERIES IN ITS MAIN ELECTRICAL SYSTEM.","options":["1","2","3"],"correct":1,"explanation":"El A320 cuenta con dos baterías (BAT 1 y BAT 2) en su sistema eléctrico principal.","taughtIn":["ele-1-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:9f391k"}},{"id":"ele-1-t4","type":"mcq","question":"IS IT POSIBLE TO DETERMINE THE SOURCE OF POWER FOR AIRCRAFT BUSES?","options":["IT IS INDICATED ON THE ELECTRICAL SCHEMATIC OVERHEAD.","NO.","ONLY WHEN OPERATING IN THE EMERGENCY ELECTRICAL CONFIGURATION.","YES, PRESS THE ECAM ELEC PUSH BUTTON AND VIEW THE ELECTRICAL SHEMATIC ON THE ECAM."],"correct":3,"explanation":"Sí: presionando el pushbutton ECAM ELEC se visualiza el esquema eléctrico completo en el ECAM, mostrando de forma clara el origen de cada bus.","taughtIn":["ele-1-c5"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1iav8h2"}}]},{"id":"ele-2","subject":"electrico","order":2,"kind":"lesson","level":1,"ident":"BUS","title":"Quién alimenta a quién","goal":"Explicar la configuración eléctrica normal en vuelo: qué alimenta cada generador y de dónde reciben energía las barras esenciales y las DC.","intro":"Hoy seguimos la energía desde los generadores hasta cada barra, tal como la ves en la página ELEC.","minutes":5,"cards":[{"id":"ele-2-c1","title":"Cada generador, su lado","body":"La red tiene dos lados. En vuelo normal, el **GEN 1** alimenta el **AC BUS 1** y el **GEN 2** alimenta el **AC BUS 2**, cada uno a través de su contactor de línea (**GLC**, generator line contactor).\n\nLos dos lados quedan separados: cada generador trabaja solo con su lado.","diagram":{"alt":"Página ELEC normal: GEN 1 alimenta AC 1 y GEN 2 alimenta AC 2; AC 1 alimenta AC ESS; TR 1 alimenta DC 1, DC BAT y DC ESS; TR 2 alimenta DC 2.","src":"assets/estaciones/diagramas/ele-ecam-normal.svg"},"keyIdea":"GEN 1 → AC BUS 1 y GEN 2 → AC BUS 2, cada uno por su GLC."},{"id":"ele-2-c2","title":"Las barras esenciales","body":"Algunas barras alimentan lo imprescindible para volar: son las barras **esenciales** (ESS).\n\nEn configuración normal, el **AC BUS 1** alimenta el **AC ESS BUS**, y del AC ESS BUS cuelga el **AC ESS SHED BUS**. El AC BUS 1 también alimenta el **TR 1**.","example":"Por eso, en la página ELEC normal, ves una línea que va de AC 1 a AC ESS.","keyIdea":"El AC BUS 1 alimenta el AC ESS BUS (y su AC ESS SHED) y el TR 1."},{"id":"ele-2-c3","title":"La red DC","body":"Los TR transforman la AC en DC:\n- el **TR 1** alimenta **DC BUS 1**, **DC BAT BUS** y **DC ESS BUS**;\n- el **TR 2** alimenta solo el **DC BUS 2**.\n\nO sea, el DC BAT BUS recibe normalmente su energía del DC BUS 1. El **ESS TR** queda en reserva.","diagram":{"alt":"Esquema de la red normal: TR 1 alimenta DC BUS 1, que alimenta DC BAT BUS y DC ESS; TR 2 alimenta DC BUS 2; ESS TR, STAT INV y EMER GEN en reserva.","src":"assets/estaciones/diagramas/ele-arquitectura.svg"},"keyIdea":"TR 1 → DC BUS 1, DC BAT BUS y DC ESS BUS. TR 2 → DC BUS 2."},{"id":"ele-2-c4","title":"Las baterías, solo cuando hace falta","body":"En vuelo normal, las baterías se conectan al DC BAT BUS solo si necesitan carga. Cuando ya están cargadas, su **battery charge limiter** (BCL) las desconecta.\n\nPor eso, la mayor parte del tiempo las baterías están desconectadas y la página ELEC muestra **0 A**.","keyIdea":"Con las baterías cargadas, el BCL las desconecta: en normal están desconectadas casi siempre."}],"test":[{"id":"ele-2-t1","type":"mcq","question":"En configuración normal de vuelo, ¿qué alimenta cada engine-driven generator?","options":["Siempre AC BUS 1","Su AC BUS asociado","GEN 1 DC, GEN 2 AC","Ambos en paralelo"],"correct":1,"explanation":"La red está dividida normalmente por lados: cada engine-driven generator alimenta su AC BUS asociado. Los contactores y bus ties permiten reconfigurarla cuando una fuente se pierde, pero esa no es la configuración normal.","taughtIn":["ele-2-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1wwjnk1"}},{"id":"ele-2-t2","type":"mcq","question":"¿Cuál es la fuente normal del AC ESS BUS?","options":["AC BUS 1","AC BUS 2","BAT 1 vía inverter","APU generator"],"correct":0,"explanation":"AC BUS 1 es la fuente normal del AC ESS BUS. La palabra clave es normal: otras configuraciones pueden alimentar cargas esenciales por rutas de respaldo.","taughtIn":["ele-2-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:psdbjl"}},{"id":"ele-2-t3","type":"mcq","question":"¿Qué buses DC suministra normalmente TR 1?","options":["DC BUS 2, DC ESS BUS y DC ESS SHED BUS","DC BUS 1, DC BAT BUS y DC ESS BUS","DC ESS BUS, DC ESS SHED BUS y HOT BUS 1","DC BUS 1 y DC BUS 2, sin alimentar el DC BAT BUS"],"correct":1,"explanation":"TR 1 convierte AC a DC para el lado 1 y, en la configuración normal descrita, además alimenta DC BAT BUS y DC ESS BUS. TR 2 queda dedicado normalmente a DC BUS 2.","taughtIn":["ele-2-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:150c3dr"}},{"id":"ele-2-t4","type":"mcq","question":"¿Qué ocurre con las baterías una vez que están completamente cargadas en configuración normal?","options":["Permanecen continuamente conectadas al DC BAT BUS","El battery charge limiter las desconecta","Alimentan permanentemente AC ESS","Se conectan en paralelo con TR 1"],"correct":1,"explanation":"Cuando las baterías están completamente cargadas, el battery charge limiter las desconecta. Ese es el comportamiento indicado para la configuración normal.","taughtIn":["ele-2-c4"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1kd9e29"}},{"id":"ele-2-t5","type":"mcq","question":"THE NUMBER 1 AC BUS CHANNEL NORMALLY SUPPLIES POWER TO ____ AND TO THE _____ BUS","options":["TR2/AC ESS SHED/DC ESS SHED.","TR1/AC ESS SHED / DC ESS.","TR1/AC ESS / AC ESS SHED.","TR1 /AC ESS / DC ESS SHED."],"correct":2,"explanation":"El AC BUS 1 alimenta normalmente al TR1 y al AC ESS BUS, y de ahí también al AC ESS SHED BUS en la cadena descendente.","taughtIn":["ele-2-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:17eki7i"}}]},{"id":"ele-3","subject":"electrico","order":3,"kind":"lesson","level":1,"ident":"TIE","title":"Prioridades y el BUS TIE","goal":"Explicar qué fuente tiene prioridad, por qué las fuentes nunca se conectan en paralelo y cómo el BUS TIE reemplaza a un generador que falla.","intro":"Hoy, las reglas del juego: quién manda cuando hay más de una fuente disponible.","minutes":7,"cards":[{"id":"ele-3-c1","title":"El orden de prioridad","body":"Cuando hay más de una fuente disponible para un lado, este es el orden:\n- primero, el **engine generator** de ese lado;\n- después, el **external power**, si el EXT PWR pb está en ON;\n- al final, el **APU GEN**.\n\nO sea, los engine generators mandan sobre el EXT PWR y el APU GEN, y el EXT PWR manda sobre el APU GEN.","keyIdea":"Prioridad: engine generator, luego EXT PWR (en ON) y luego APU GEN."},{"id":"ele-3-c2","title":"Nunca en paralelo","body":"Dos generadores **nunca** se conectan en paralelo: cada barra recibe energía de una sola fuente a la vez.\n\nCuando cambia la fuente, los contactores abren una conexión y cierran otra, y la barra pasa de un generador al otro.","example":"Con el APU GEN alimentando en tierra, al apretar el EXT PWR pb el external power toma la red y el APU GEN deja de alimentar: nunca quedan los dos juntos.","keyIdea":"Los generadores nunca se conectan en paralelo."},{"id":"ele-3-c3","title":"Un generador puede con todo","body":"Un solo engine generator puede alimentar toda la red, con una excepción: el **DC BUS Ent**, la barra del entretenimiento de pasajeros, en los aviones que la tienen.\n\nAsí, perder un generador no deja sin energía ningún sistema del avión.","more":"El DC BUS Ent necesita dos generadores, salvo en tierra, donde basta el APU GEN (si no está sobrecargado) o el external power.","keyIdea":"Un engine generator alimenta toda la red, menos el DC BUS Ent."},{"id":"ele-3-c4","title":"El BUS TIE","body":"Entre los dos lados están los **bus tie contactors** (BTC). Con el **BUS TIE pb** en AUTO se abren y se cierran solos, para que AC BUS 1 y AC BUS 2 tengan siempre energía:\n- normal: los dos abiertos;\n- un engine generator en un lado y el APU GEN o el EXT PWR en el otro: se cierra uno;\n- una sola fuente para todo: se cierran los dos.\n\nCon el BUS TIE pb en OFF, los dos se abren.","diagram":{"alt":"Tres casos del BUS TIE: normal con los BTC abiertos; falla del GEN 2 con el APU GEN alimentando AC BUS 2 por el BTC 2; falla del GEN 2 sin APU, con GEN 1 alimentando ambos lados por los dos BTC.","src":"assets/estaciones/diagramas/ele-bus-tie.svg"},"keyIdea":"En AUTO, los BTC se cierran solos para que ambos AC BUS tengan energía; en OFF quedan abiertos."},{"id":"ele-3-c5","title":"Si falla un generador","body":"Si un engine generator falla, el sistema lo reemplaza solo:\n- con el **APU GEN**, si está disponible;\n- si no, con el **otro engine generator**, a través del BUS TIE.\n\nCon un generador menos, además se corta automáticamente parte de la carga de los galleys.","example":"Falla el GEN 2 en crucero y arrancas el APU: el GEN 1 sigue con el AC BUS 1 y el APU GEN toma el AC BUS 2.","keyIdea":"Falla un GEN: lo reemplaza el APU GEN o, si no, el otro GEN por el BUS TIE."}],"test":[{"id":"ele-3-t1","type":"mcq","question":"En operación normal, ¿qué fuentes tienen mayor prioridad para alimentar la red AC?","options":["El APU generator por sobre cualquier otra fuente","Engine generators sobre EXT PWR y APU GEN","External power siempre por sobre los engine generators","Las baterías por sobre los generadores"],"correct":1,"explanation":"La arquitectura prioriza la fuente propia de cada motor cuando está disponible. Así se evita mantener una fuente auxiliar o externa como alimentación primaria durante la operación normal; GEN 1 y GEN 2 desplazan tanto al APU generator como al external power.","taughtIn":["ele-3-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:mzkje0"}},{"id":"ele-3-t2","type":"mcq","question":"Si EXT PWR está seleccionado ON y sus parámetros son válidos, ¿qué prioridad tiene respecto del APU generator?","options":["El APU siempre tiene prioridad","EXT PWR tiene prioridad sobre APU GEN","Se conectan ambos en paralelo","La prioridad depende del lado del avión"],"correct":1,"explanation":"Cuando EXT PWR se selecciona ON, la lógica prefiere la fuente externa antes que el APU generator. Esto evita usar innecesariamente el APU cuando una fuente de tierra válida ya puede alimentar la red.","taughtIn":["ele-3-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:ow2wg7"}},{"id":"ele-3-t3","type":"mcq","question":"¿Pueden conectarse en paralelo los generadores del A320?","options":["Sí; durante takeoff para compartir carga entre los dos engine generators","Sí; pero solamente entre APU GEN y GEN 1 cuando ambos AC buses están activos","No; la arquitectura impide conectar las fuentes generadoras en paralelo","Sí; únicamente en emergency electrical configuration con RAT desplegado"],"correct":2,"explanation":"No. Dos generadores nunca se conectan en paralelo: cada barra recibe energía de una sola fuente a la vez, y los contactores la pasan de una fuente a otra.","taughtIn":["ele-3-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1o6gm10"}},{"id":"ele-3-t4","type":"mcq","question":"Si queda disponible un solo engine generator, ¿qué puede alimentar?","options":["Solo su AC BUS y las cargas no esenciales asociadas","Toda la red excepto DC BUS Entertainment","Solo AC ESS BUS, DC ESS BUS y cargas esenciales","Solo AC BUS 1, AC ESS BUS y sus cargas asociadas"],"correct":1,"explanation":"Un solo engine generator puede alimentar toda la red. La única excepción es el DC BUS Ent, del entretenimiento de pasajeros, que en vuelo necesita dos generadores.","taughtIn":["ele-3-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1z0aht"}},{"id":"ele-3-t5","type":"mcq","question":"THE PURPOSE OF THE AUTO BUS TIE IS TO ALLOW EITHER ENGINE-DRIVEN IDG TO AUTOMATICALLY POWER BOTH MAIN AC BUSES IN THE EVENT OF A GENERATOR LOSS UNTIL EITHER GROUND POWER OR THE APU GENERATOR IS ACTIVATED.","options":["TRUE","FALSE"],"correct":0,"explanation":"Verdadero: la función automática del bus tie permite que el IDG restante alimente ambos AC BUS principales ante la pérdida de un generador, hasta que otra fuente (tierra o APU) quede disponible.","taughtIn":["ele-3-c4","ele-3-c5"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:143vdp5"}},{"id":"ele-3-t6","type":"mcq","question":"DURING A ROUTINE FLIGHT, WHICH OF THE FOLLOWING WOULD RESULT AFTER THE LOSS OF GEN #2 AND THE SUBSEQUEND START OF THE APU?","options":["THE APU WOULD NOW POWER BOTH SIDES OF THE ELECTRICAL SYSTEM.","ALL SYSTEMS RETURN TO NORMAL AND THE RAT MUST BE RESTORED.","ENG GEN #1 CONTINUES TO POWER AC BUS #1 AND DOWNSTREAM SYSTEMS. THE APU POWERS AC BUS #2 AND DOWNSTREAM SYSTEMS."],"correct":2,"explanation":"El generador del motor 1 sigue alimentando el AC BUS 1 y sus sistemas, mientras que el APU, una vez arrancado, alimenta específicamente el AC BUS 2 (el lado que perdió su generador), no ambos lados simultáneamente.","taughtIn":["ele-3-c5"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:dr1jlj"}}]},{"id":"ele-4","subject":"electrico","order":4,"kind":"lesson","level":2,"ident":"EXT","title":"External power, APU GEN y galleys","goal":"Explicar cómo se conecta el external power, cómo pasar al APU GEN y cuándo se cortan los galleys.","intro":"Hoy bajamos a la rampa: external power, APU GEN y los galleys.","minutes":6,"cards":[{"id":"ele-4-c1","title":"AVAIL y ON","body":"El **EXT PWR pb** tiene dos luces:\n- **AVAIL** (verde): el external power está enchufado y sus parámetros son normales, pero todavía no alimenta el avión.\n- **ON** (azul): al apretar el pb se cierra el **external power line contactor**, y la energía entra a la red.\n\nOjo: la luz ON sigue encendida aunque después los engine generators tomen la red.","more":"Para servicios en tierra sin energizar todo el avión está el MAINT BUS switch, en la entrada delantera. Con el external power conectado, energiza solo las barras AC y DC GND/FLT: luces de cabina, carga de combustible y la bomba eléctrica del Yellow, entre otras.","diagram":{"alt":"Panel ELEC del overhead: arriba COMMERCIAL, baterías y AC ESS FEED; abajo IDG 1, GEN 1, APU GEN, BUS TIE, EXT PWR con AVAIL y ON, GEN 2 e IDG 2; y GALY & CAB.","src":"assets/estaciones/diagramas/ele-panel.svg"},"keyIdea":"AVAIL: disponible y normal. Al apretarlo (ON), se cierra el external power line contactor."},{"id":"ele-4-c2","title":"Del EXT PWR al APU GEN","body":"Con el **APU GEN pb** en ON, el generador del APU se energiza, pero su contactor solo se cierra si el contactor del external power está abierto.\n\nComo el EXT PWR manda sobre el APU GEN, para pasar a la energía del APU hay que **apretar el EXT PWR pb** y desconectarlo.\n\nCon el APU GEN pb en OFF, el campo del generador se desenergiza y su contactor se abre.","keyIdea":"Para pasar al APU GEN hay que desconectar el EXT PWR (apretar su pb)."},{"id":"ele-4-c3","title":"Los galleys se cortan solos","body":"Los galleys son de las cargas más grandes del avión. Para no sobrecargar lo que queda, se cortan (shed) automáticamente:\n- en vuelo, cuando opera **un solo generador**;\n- en tierra, cuando alimenta un solo engine generator.\n\nCon el APU GEN o el EXT PWR alimentando en tierra, los galleys funcionan todos. Cuando se cortan, la página ELEC muestra **GALLEY SHED**.","keyIdea":"En vuelo, el main galley se corta solo cuando queda un generador; el ECAM muestra GALLEY SHED."},{"id":"ele-4-c4","title":"La luz FAULT del galley","body":"El **GALY & CAB pb** (GALLEY pb en algunos aviones) controla los galleys y otras cargas de cabina. En OFF, los corta.\n\nSu luz **FAULT** se enciende cuando algún generador tiene una carga mayor al **100 %** de su capacidad (rated output).","keyIdea":"GALY & CAB FAULT: algún generador sobre el 100 % de su carga."}],"test":[{"id":"ele-4-t1","type":"mcq","question":"¿Qué significa la indicación verde AVAIL del EXT PWR?","options":["External power está conectado y sus parámetros eléctricos están dentro de límites","External power ya está alimentando todos los buses principales de la aeronave","El APU generator está disponible para sustituir a external power cuando se seleccione","Las baterías están cargándose y el DC BAT BUS recibe alimentación externa"],"correct":0,"explanation":"AVAIL confirma calidad y disponibilidad de la fuente externa, no que esté conectada a la red. El paso adicional es seleccionar el pushbutton para cerrar el external power line contactor.","taughtIn":["ele-4-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1p7lryn"}},{"id":"ele-4-t2","type":"mcq","question":"¿Qué acción eléctrica produce seleccionar EXT PWR ON?","options":["Cierra EXT PWR line contactor","Abre el external power line contactor","Cierra el APU generator line contactor","Abre ambos engine generator contactors"],"correct":0,"explanation":"Al seleccionar EXT PWR ON, cierra el external power line contactor. AVAIL y ON describen estados distintos: disponibilidad de la fuente y conexión a la red.","taughtIn":["ele-4-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1l2600g"}},{"id":"ele-4-t3","type":"mcq","question":"HAVING STARTING THE APU, HOW CAN YOU GET THE APU GENERATOR TO POWER THE ELECTRICAL SYSTEM?","options":["THE APU GENERATOR MUST BE SWITCH ON.","BY PUSHING THE EXT PWR PUSHBUTTON THUS DISCONNECTING THE EXTERNAL POWER.","BY PUSHING THE BUS TIE PUSHBUTTON","YOU ARE UNABLE TO AS THE APU POWER OUTPUT IS OUTSIDE NORMAL PARAMETERS."],"correct":1,"explanation":"Si la energía externa ya está conectada y alimentando el sistema, para que el generador del APU tome el control se debe presionar el pushbutton EXT PWR, desconectando la energía externa; el APU no desplaza automáticamente a una fuente de mayor prioridad ya conectada.","taughtIn":["ele-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1g60mth"}},{"id":"ele-4-t4","type":"mcq","question":"WHAT IS THE FUNCTION OF APU GEN PUSH BUTTON LOCATED ON THE OVERHEAD ELECTRICAL PANEL?","options":["PUSH THIS BUTTON TO AUTOMATICALLY START THE APU","WHEN SELECTED TO OFF THE APU GENERATOR FIELD IS DE-ENERGIZED.","BOTH ARE CORRECT."],"correct":1,"explanation":"El pushbutton APU GEN, al seleccionarse en OFF, desenergiza el campo del generador del APU; no es este pushbutton el que arranca el APU, esa es una función separada.","taughtIn":["ele-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:q07ze2"}},{"id":"ele-4-t5","type":"mcq","question":"¿Cuándo se shed automáticamente el main galley en vuelo?","options":["Cuando opera un solo generador","Solo cuando se pierde AC ESS","Cada vez que se selecciona APU GEN","Únicamente durante el engine start"],"correct":0,"explanation":"En vuelo, el main galley se corta (shed) automáticamente cuando opera un solo generador, para no sobrecargarlo.","taughtIn":["ele-4-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1rwzh9i"}},{"id":"ele-4-t6","type":"mcq","question":"¿Qué condición enciende la luz FAULT del GALLEY/GALY & CAB pb?","options":["Load superior al 100 % del rated output en algún generator","Galley supply seleccionado manualmente OFF","APU GEN disponible pero no conectado a la red","External power desconectado con ambos engine generators disponibles"],"correct":0,"explanation":"La luz FAULT se enciende cuando la carga de algún generator supera el 100 % de su rated output.","taughtIn":["ele-4-c4"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1nsascg"}}]},{"id":"ele-5","subject":"electrico","order":5,"kind":"lesson","level":2,"ident":"IDG","title":"El IDG y la falla de un generador","goal":"Explicar qué es el IDG, qué enciende su luz FAULT, cómo y cuándo se desconecta, y qué pasa al perder un generador.","intro":"Hoy abrimos el generador del motor: el IDG.","minutes":6,"cards":[{"id":"ele-5-c1","title":"¿Qué es el IDG?","body":"El motor no gira siempre igual, pero la red necesita **400 Hz** constantes. Por eso cada generador de motor va dentro de un **IDG** (Integrated Drive Generator): un integrated drive que entrega un giro constante, unido al generador.\n\nLa **GCU** (Generator Control Unit) regula el voltaje y la frecuencia, y protege la red abriendo o cerrando el GLC.","diagram":{"alt":"El motor mueve el IDG, formado por el integrated drive de giro constante y el generador; la GCU regula y conecta el generador al AC BUS por el GLC. Al lado, las causas de la luz FAULT y las reglas del IDG pb.","src":"assets/estaciones/diagramas/ele-idg.svg"},"keyIdea":"IDG: integrated drive de giro constante más generador; la GCU regula y protege."},{"id":"ele-5-c2","title":"La luz FAULT del IDG","body":"La luz ámbar **FAULT** del IDG pb avisa un problema del aceite del IDG:\n- el aceite de salida está sobre **180 °C**, o\n- la presión de aceite está baja (no se avisa con el motor a muy bajas vueltas).\n\nLa luz se apaga cuando el IDG queda desconectado. Si el aceite llega a **200 °C**, el IDG se desconecta solo.","keyIdea":"IDG FAULT: aceite sobre 180 °C o baja presión de aceite."},{"id":"ele-5-c3","title":"Desconectar el IDG","body":"El **IDG pb** tiene guarda. Al apretarlo, el IDG se separa de su eje y el generador deja de girar. Tres reglas:\n- no mantenerlo apretado más de **3 s**, porque se daña el mecanismo;\n- hacerlo solo con el motor girando (o en windmilling); si no, el IDG se daña al arrancar el motor;\n- es definitivo: solo mantenimiento lo reconecta, así que **en vuelo no se reconecta**.","keyIdea":"IDG pb: máximo 3 s y con el motor girando; en vuelo no se reconecta."},{"id":"ele-5-c4","title":"Si se pierde un generador","body":"Si falla o se desconecta un IDG, se pierde ese generador, pero **ninguna barra principal** se queda sin energía: el APU GEN o el otro generador toman ese lado por el BUS TIE.\n\nMientras opere un solo generador, el **main galley** se corta automáticamente. La página ELEC muestra **GALLEY SHED** como recordatorio.","example":"Desconectas el IDG 1 en crucero y no tienes APU: el GEN 2 alimenta las dos barras AC y aparece GALLEY SHED.","keyIdea":"Se pierde un generador: ninguna barra principal sin energía; con un solo generador, el main galley se corta solo."}],"test":[{"id":"ele-5-t1","type":"mcq","question":"THE IDG FAULT LIGHT INDICATES:","options":["AN IDG OIL OVERHEATS.","IDG LOW OIL PRESSURE.","IDG HAS BEEN DISCONNECTED.","EITHER A OR B."],"correct":3,"explanation":"La luz FAULT del IDG se enciende ante sobrecalentamiento del aceite o ante baja presión de aceite; cualquiera de esas dos condiciones puede dispararla.","taughtIn":["ele-5-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:r2pe4y"}},{"id":"ele-5-t2","type":"mcq","question":"ARE THERE ANY LIMITATIONS ASSOCIATED WITH DISCONNECTING AN IDG?","options":["NEVER DISCONNECT AN IDG IN FLIGHT, OR PUSH THE IDG DISCONNECT PUSH BUTTON FOR MORE THEN 30 SECONDS.","THERE IS NO LIMITATIONS.","NEVER DISCONNECT AN IDG IN FLIGHT, OR PUSH THE IDG DISCONNECT PUSH BUTTON FOR MORE THEN 5 SECONDS.","NEVER DISCONNECT AN IDG UNLESS THE ENGINE IS RUNNING NOR PUSH THE IDG DISCONNECT PUSH BUTTON FOR MORE THEN 3 SECONDS."],"correct":3,"explanation":"Un IDG nunca debe desconectarse a menos que el motor esté en marcha, y el pushbutton de desconexión no debe presionarse por más de 3 segundos, para no dañar el mecanismo de desconexión.","taughtIn":["ele-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:cgu4hk"}},{"id":"ele-5-t3","type":"mcq","question":"CAN YOU RECONNECT AN IDG IN FLIGHT?","options":["YES, BUT ONLY AFTER CONTACTING MAINTENANCE CONTROL.","YES,PUSH AND HOLD THE IDG PB UNTIL THE GEN FAULT LIGHT IS NO LONGER ILLUMINATED.","NO.","NONE OF THE ABOVE."],"correct":2,"explanation":"No: una vez desconectado, un IDG solo puede reconectarse mediante una acción de mantenimiento en tierra, nunca durante el vuelo.","taughtIn":["ele-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:sr873a"}},{"id":"ele-5-t4","type":"mcq","question":"IF BOTH ENGINE GENERATORS ARE POWERING THE SYSTEM, AND ONE SUBSEQUENTLY FAILS ARE ANY BUSES UNPOWERED?","options":["ONLY THE AC ESS SHED BUS","NO, BUT SOME LOADS ARE SHED IN BOTH MAIN GALLEYS","YES, THOSE ASSOCIATED WITH THE FAILED GENERATOR"],"correct":1,"explanation":"Ninguna barra principal queda sin energía: el generador que queda, o el APU GEN, toma el lado que falló por el BUS TIE. Con un solo generador funcionando, se corta automáticamente parte de la carga de los galleys.","taughtIn":["ele-5-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1oavpuu"}},{"id":"ele-5-t5","type":"mcq","question":"AFTER IDG DISCONNECTION WHY DO YOU GET A GALLEY SHED INDICATION ON THE SD?","options":["IT IS A REMINDER TO PUSH THE GALLEY PUSHBUTTON TO MANUALLY SHED THE MAIN GALLEY.","IT IS A REMINDER TO GET THE FLIGHT ATTENDANTS TO SWITCH OFF GALLEY EQUIPMENT TO DECREASE THE LOAD ON THE REMAINING GENERATOR.","IF IT IS A REMINDER THAT THE MAIN GALLEY HAS BEEN SHED AUTOMATICALLY FOLLOWING THE LOSS OF ONE GENERATOR."],"correct":2,"explanation":"El shed del galley principal ocurre de forma automática cuando queda un solo generador operando (tras perder un IDG), y el indicador en el SD es solo un recordatorio de esa acción automática, no un pedido a la tripulación de cabina de apagar equipos.","taughtIn":["ele-5-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1uzmtmm"}}]},{"id":"ele-6","subject":"electrico","order":6,"kind":"lesson","level":2,"ident":"BAT","title":"Las baterías","goal":"Explicar cómo están conectadas las baterías, quién las controla, qué muestra su indicación y cómo se protegen en tierra.","intro":"Hoy, las dos baterías: siempre presentes, pero casi nunca conectadas a la red.","minutes":6,"cards":[{"id":"ele-6-c1","title":"Dos baterías y sus HOT BUS","body":"El A320 tiene **dos baterías** de 23 Ah. Cada una está conectada **siempre** a su **HOT BUS** (HOT BUS 1 y HOT BUS 2): esas barras tienen energía incluso con todo el avión apagado.\n\nHacia el resto de la red, cada batería se conecta al **DC BAT BUS** por su propio contactor.","diagram":{"alt":"DC BUS 1 alimenta el DC BAT BUS. El BCL cierra el contactor de BAT 1 para cargarla y deja abierto el de BAT 2, ya cargada. Los HOT BUS cuelgan siempre de las baterías. El overhead muestra el voltaje.","src":"assets/estaciones/diagramas/ele-baterias.svg"},"keyIdea":"Las baterías están siempre conectadas a su HOT BUS; al DC BAT BUS, por su contactor."},{"id":"ele-6-c2","title":"El BCL decide","body":"Cada batería tiene un **BCL** (Battery Charge Limiter). El BCL vigila la carga y **abre o cierra el battery line contactor**: así conecta la batería al DC BAT BUS cuando hace falta y la desconecta cuando no.\n\nEl **BAT pb** en AUTO deja trabajar al BCL. En OFF, el BCL no opera y el contactor queda abierto, pero los HOT BUS siguen con energía.","keyIdea":"BAT pb en AUTO: el BCL controla el battery line contactor."},{"id":"ele-6-c3","title":"La indicación BAT","body":"Junto a cada BAT pb, en el overhead, una indicación muestra el **voltaje** de la batería.\n\nSi el avión estuvo 6 h o más sin energía, antes del vuelo se revisa ese voltaje con los BAT pb en OFF: debe ser **mayor a 25.5 V**, lo que asegura una carga sobre 50 %.","keyIdea":"La indicación BAT muestra el voltaje; antes del vuelo, sobre 25.5 V."},{"id":"ele-6-c4","title":"Si les falta carga","body":"Con 25.5 V o menos, las baterías se cargan con la energía del avión: **BAT pb en AUTO** y **EXT PWR en ON**. En la página ELEC se comprueba que el contactor esté cerrado y que las baterías estén cargando.\n\nEl ciclo de carga dura unos **20 min**; después se revisa de nuevo el voltaje.","keyIdea":"Con 25.5 V o menos: BAT en AUTO y EXT PWR en ON, unos 20 min de carga."},{"id":"ele-6-c5","title":"Protección en el estacionamiento","body":"Con el avión estacionado, una lógica automática evita que las baterías se descarguen por completo.\n\nSi el avión está en tierra, con los BAT pb en AUTO, sin external power ni generadores, y el voltaje está bajo, los contactores de las baterías se abren solos. Para volver a conectarlas: BAT pb en OFF y luego en AUTO.","keyIdea":"En tierra, la cut-off logic desconecta las baterías para que no se descarguen del todo."}],"test":[{"id":"ele-6-t1","type":"mcq","question":"¿Qué muestra directamente la indicación BAT 1(2) del overhead electrical panel?","options":["Battery voltage","Battery charging current","DC BAT BUS load","Battery temperature"],"correct":0,"explanation":"La indicación del panel es de voltaje. La lógica de carga usa además corriente y otros parámetros, pero el valor mostrado como BAT IND corresponde a la tensión de la batería.","taughtIn":["ele-6-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1oj37ny"}},{"id":"ele-6-t2","type":"mcq","question":"¿Qué elemento controla el BAT 1(2) pushbutton en AUTO?","options":["El Battery Charge Limiter (BCL)","La frecuencia del inverter","El emergency generator","El contactor del APU"],"correct":0,"explanation":"El BAT pushbutton actúa sobre el BCL, que decide la conexión/desconexión de la batería al DC BAT BUS mediante su line contactor.","taughtIn":["ele-6-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1wgf6y7"}},{"id":"ele-6-t3","type":"mcq","question":"¿Cómo conecta o desconecta físicamente el BCL una batería del DC BAT BUS?","options":["Mediante el battery line contactor","Mediante el AC ESS FEED contactor","A través del static inverter contactor","Abriendo o cerrando el TR1 output breaker"],"correct":0,"explanation":"El BCL gobierna el battery line contactor. Esa es la interfaz que une o separa cada batería del DC BAT BUS según la lógica automática.","taughtIn":["ele-6-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1v6lznp"}},{"id":"ele-6-t4","type":"mcq","question":"IF THE BATTERY VOLTAGES ARE BELOW THE MINIMUM, HOW DO YOU CHARGE THEM?","options":["YOU HAVE TO CALL A MECHANIC BECAUSE THE BATTERIES CAN LONLY BE CHARGED BY MAINTENANCE.","I HAVE TO CHECK THAT THE BAT PUSHBUTTONS ARE ON AND SWITCH THE EXTERNAL POWER ON"],"correct":1,"explanation":"Las baterías se cargan con la energía del avión: BAT pb en AUTO (su posición normal, que aquí llaman ON) y EXT PWR en ON. No hace falta mantenimiento.","taughtIn":["ele-6-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:88m8sg"}},{"id":"ele-6-t5","type":"mcq","question":"BOTH BATTERIES ARE CHARGED BY THE EXTERNAL POWER UNIT. APPROXIMATELY HOW LONG DOES THE CHARGING PROCESS TAKE?","options":["L0 MINUTES.","20 MINUTES.","30 MINUTES.","BETWEEN 30 & 45 MINUTES."],"correct":1,"explanation":"El proceso de carga de ambas baterías mediante energía externa toma aproximadamente 20 minutos.","taughtIn":["ele-6-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:u03uc4"}},{"id":"ele-6-t6","type":"mcq","question":"¿Qué objetivo tiene la automatic battery cut-off logic cuando la aeronave está estacionada en tierra?","options":["Evitar una descarga completa de las baterías","Mantener las baterías conectadas siempre","Aumentar la carga del galley","Alimentar los AC buses por horas"],"correct":0,"explanation":"La lógica abre los contactores en condiciones de estacionamiento y bajo voltaje para proteger las baterías de una descarga profunda cuando desaparece la alimentación principal.","taughtIn":["ele-6-c5"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:52o0p5"}}]},{"id":"ele-7","subject":"electrico","order":7,"kind":"lesson","level":3,"ident":"BCL","title":"Cuándo se conectan las baterías","goal":"Explicar en qué casos el BCL conecta las baterías al DC BAT BUS y cómo empieza y termina el ciclo de carga.","intro":"Hoy, la letra chica del BCL: cuándo conecta las baterías y por cuánto tiempo.","minutes":5,"cards":[{"id":"ele-7-c1","title":"Para arrancar el APU","body":"El arranque del APU usa las baterías. Con el **APU MASTER SW** en ON, el BCL conecta las baterías al DC BAT BUS mientras la velocidad del APU (N) esté **bajo 95 %**.\n\nSi en ese momento está funcionando el **emergency generator**, esa conexión se limita a **3 min**.","diagram":{"alt":"Los tres casos en que la batería se conecta al DC BAT BUS: arranque del APU, carga bajo 26.5 V hasta que la corriente baja de 4 A, y emergencia bajo 100 kt sin EMER GEN.","src":"assets/estaciones/diagramas/ele-carga.svg"},"keyIdea":"APU start: baterías conectadas con MASTER SW ON y N bajo 95 % (máximo 3 min con el EMER GEN)."},{"id":"ele-7-c2","title":"Cuándo empieza la carga","body":"El BCL también conecta una batería para cargarla cuando su voltaje baja de **26.5 V**.\n\nLa batería se carga con la energía del DC BAT BUS, que normalmente viene del TR 1.","keyIdea":"La carga empieza cuando el voltaje baja de 26.5 V."},{"id":"ele-7-c3","title":"Cuándo termina","body":"Mientras la batería se carga, la corriente de carga va bajando. El ciclo termina cuando esa corriente baja de **4 A**:\n- en tierra, la batería se desconecta **de inmediato**;\n- en vuelo, se desconecta **30 min después**.","example":"En vuelo, aunque la corriente ya bajó de 4 A, la batería sigue conectada media hora más antes de que el BCL la desconecte.","keyIdea":"Termina con la corriente bajo 4 A: en tierra al tiro, en vuelo 30 min después."},{"id":"ele-7-c4","title":"En emergencia","body":"Hay un tercer caso: si se pierden AC BUS 1 y AC BUS 2 **bajo 100 kt** y el emergency generator no alimenta, el BCL conecta las baterías al DC BAT BUS.\n\nLo verás completo en la estación de solo baterías.","keyIdea":"Sin AC BUS 1 ni 2, bajo 100 kt y sin EMER GEN: baterías al DC BAT BUS."}],"test":[{"id":"ele-7-t1","type":"mcq","question":"Durante el arranque del APU, con APU MASTER ON, ¿hasta qué condición de APU N permanecen conectadas las baterías al DC BAT BUS?","options":["Con APU MASTER ON mientras APU N sea menor de 95 %","Solo después de que aparezca APU AVAIL","Únicamente si ambos engine generators están conectados","Solo si la aeronave está en vuelo por encima de 100 kt"],"correct":0,"explanation":"La batería participa en la secuencia de arranque antes de que el APU alcance velocidad suficiente. La conexión se mantiene con MASTER ON mientras N está por debajo de 95 %.","taughtIn":["ele-7-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:141t52i"}},{"id":"ele-7-t2","type":"mcq","question":"Si el emergency generator está funcionando, ¿qué limitación temporal aplica a la conexión de baterías durante APU start?","options":["La conexión está limitada a 3 min","La conexión está limitada a 30 s","Las baterías no pueden conectarse en absoluto","La conexión permanece ilimitada hasta APU AVAIL"],"correct":0,"explanation":"Si el emergency generator está funcionando, la conexión de las baterías para arrancar el APU se limita a 3 min.","taughtIn":["ele-7-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1t403cl"}},{"id":"ele-7-t3","type":"mcq","question":"¿Qué condición de battery voltage inicia un ciclo de carga automática?","options":["Por debajo de 26.5 V","Por encima de 29.5 V","Exactamente a 24.0 V","Por debajo de 20 V"],"correct":0,"explanation":"El BCL conecta la batería para cargarla cuando la tensión cae por debajo de 26.5 V, siempre dentro de la lógica normal del sistema.","taughtIn":["ele-7-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1veezl"}},{"id":"ele-7-t4","type":"mcq","question":"¿Qué parámetro determina que termine normalmente un charging cycle?","options":["Que la battery charge current baje de 4 A","Que la battery voltage alcance exactamente 30 V","Que el DC ESS BUS quede sin carga durante 5 min","Que ambas batteries tengan idéntica temperatura"],"correct":0,"explanation":"El BCL interpreta que la batería está suficientemente cargada cuando la corriente de carga cae por debajo de 4 A; el momento de desconexión depende de tierra/vuelo.","taughtIn":["ele-7-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:dus9xb"}},{"id":"ele-7-t5","type":"mcq","question":"Una vez que la charging current baja de 4 A, ¿qué diferencia existe entre tierra y vuelo?","options":["En tierra termina de inmediato; en vuelo, tras 30 min","En vuelo termina inmediatamente; en tierra espera 30 min","En ambos casos siempre espera exactamente 30 min","En tierra la batería permanece conectada hasta engine shutdown"],"correct":0,"explanation":"Cuando la corriente de carga baja de 4 A, en tierra la batería se desconecta de inmediato; en vuelo, el BCL espera 30 min antes de desconectarla.","taughtIn":["ele-7-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1iezd9y"}},{"id":"ele-7-t6","type":"mcq","question":"Si AC BUS 1 y 2 se pierden por debajo de 100 kt y el EMER GEN no alimenta, ¿qué hace la lógica de baterías?","options":["Conecta las baterías al DC BAT BUS","Desconecta ambas baterías para conservarlas","Arranca automáticamente el APU sin intervención","Conecta el main galley al HOT BUS para reducir la carga"],"correct":0,"explanation":"Por debajo de 100 kt la red de emergencia depende de las baterías cuando no existe generación AC principal ni emergency generator disponible.","taughtIn":["ele-7-c4"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1cwp7ii"}}]},{"id":"ele-8","subject":"electrico","order":8,"kind":"lesson","level":3,"ident":"TRU","title":"Fallas parciales: TR, AC BUS 1 y humo","goal":"Explicar qué pasa si falla un TR o el AC BUS 1, qué hace el GEN 1 LINE en un humo y cuál es la regla de los circuit breakers.","intro":"Hoy, fallas a medias: cuando se pierde solo una parte de la red.","minutes":6,"cards":[{"id":"ele-8-c1","title":"Si falla un TR","body":"Cada TR abre su contactor solo si se recalienta o si su corriente cae al mínimo. Entonces:\n- el **otro TR** toma su lugar;\n- el **ESS TR** pasa a alimentar el **DC ESS BUS**.\n\nSi fallan **TR 1 y TR 2**, se pierden DC BUS 1, DC BUS 2 y DC BAT BUS, pero el DC ESS BUS sigue con energía gracias al ESS TR.","keyIdea":"Falla un TR: el otro lo reemplaza y el ESS TR alimenta el DC ESS BUS."},{"id":"ele-8-c2","title":"Si falla el AC BUS 1","body":"El AC ESS BUS normalmente cuelga del AC BUS 1. Si se pierde el AC BUS 1:\n- con el **AC ESS FEED pb** en ALTN, el **AC BUS 2** alimenta el AC ESS BUS, y el ESS TR alimenta el DC ESS BUS;\n- a los 5 s, el **DC BUS 2** alimenta el DC BUS 1 y el DC BAT BUS.","more":"En algunos aviones el AC BUS 2 toma el AC ESS BUS automáticamente al perderse el AC BUS 1, sin tocar el AC ESS FEED pb. La luz FAULT del pb se enciende cuando el AC ESS BUS se queda sin energía.","diagram":{"alt":"Página ELEC con falla de AC BUS 1: AC 1 y TR 1 sin energía; AC 2 alimenta AC ESS y, por el ESS TR, DC ESS; DC 2 alimenta DC BAT y DC 1.","src":"assets/estaciones/diagramas/ele-ecam-ac1.svg"},"keyIdea":"El AC ESS FEED pasa la fuente del AC ESS BUS del AC BUS 1 al AC BUS 2."},{"id":"ele-8-c3","title":"GEN 1 LINE en un humo","body":"En el panel EMER ELEC PWR está el **GEN 1 LINE pb**. En OFF abre el contactor de línea del GEN 1: el GEN 1 sale de todas las barras, pero **sigue alimentando una bomba de combustible en cada ala**. El AC BUS 1 pasa a recibir energía del GEN 2 por el BUS TIE.\n\nSe usa en el procedimiento de humo, para llegar a la configuración eléctrica de emergencia.","keyIdea":"GEN 1 LINE OFF: el GEN 1 sale de las barras, pero sigue con una bomba de combustible en cada ala."},{"id":"ele-8-c4","title":"La configuración de humo","body":"En el procedimiento de humo se cortan las barras principales y la red queda como en la emergencia eléctrica: se apaga cerca del **75 %** del equipo eléctrico.\n\nLo que sigue funcionando se alimenta a través de los **circuit breakers del overhead panel** (salvo lo que cuelga de los HOT BUS). Por eso esos C/B son los que importan en la configuración de emergencia.","keyIdea":"En emergencia o en humo, lo que sigue funcionando pasa por los C/B del overhead."},{"id":"ele-8-c5","title":"Los circuit breakers","body":"Hay C/B **verdes** (monitoreados) y **negros**. Si un C/B verde salta y queda afuera más de 1 min, el ECAM muestra **C/B TRIPPED** con su ubicación.\n\nEn vuelo, un C/B que saltó solo **no se vuelve a meter**, salvo que el comandante lo considere necesario para seguir el vuelo con seguridad, y entonces **una sola vez**.","keyIdea":"En vuelo, un C/B saltado no se resetea salvo necesidad, y solo una vez."}],"test":[{"id":"ele-8-t1","type":"mcq","question":"AN AC ESS FEED SWITCH LOCATED ON THE OVERHEAD PANEL SHIFTS THE POWER SOURCE FOR THE AC ESS BUS FROM:","options":["AC BUS 1 TO AC BUS 2","AC BUS 1 TO AC GRND/FIT BUS","AC BUS 2 TO AC BUS 1"],"correct":0,"explanation":"El switch AC ESS FEED permite pasar la fuente del AC ESS BUS de AC BUS 1 (su fuente normal) a AC BUS 2 como alternativa, no al revés ni hacia el AC GRND/FLT BUS.","taughtIn":["ele-8-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:19h4vgk"}},{"id":"ele-8-t2","type":"mcq","question":"WHAT IS THE FUNCTION OF THE GEN 1 LINE PUSH BUTTON?","options":["WHEN SELECTED OFF THE AVIONICS COMPARTMENT ISOLATION VALVES CLOSE.","WHEN SELECTED OFF THE #1 GENERATOR POWERS ALL AC BUSES.","WHEN SELECTED OFF GENERATOR #1 IS REMOVED FROM ALL BUSSES BUT CONTINUES TO POWER ONE FUEL PUMP IN EACH WING."],"correct":2,"explanation":"Al seleccionar GEN 1 LINE en OFF, el generador 1 queda removido de todas las barras, pero continúa alimentando una bomba de combustible en cada ala, una excepción específica de esta función de aislamiento (usada, entre otras cosas, en el drill de humo).","taughtIn":["ele-8-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:j8i8m2"}},{"id":"ele-8-t3","type":"mcq","question":"WHAT IS THE SIGNIFICANCE OF THE CIRCUIT BREAKERS ON THE OVERHEAD PANEL?","options":["THEY ARE NOT MONITORED BY ECAM.","CANNOT BE RESET.","THEY MAY BE OPERATIONAL IN THE EMERGENCY ELECTRICAL CONFIGURATION."],"correct":2,"explanation":"Los circuit breakers del panel overhead pueden seguir siendo operativos incluso en configuración eléctrica de emergencia, a diferencia de otros paneles de CB que podrían quedar sin energía.","taughtIn":["ele-8-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:14fbdto"}},{"id":"ele-8-t4","type":"mcq","question":"HOW MANY TIMES CAN YOU RESET A CIRCUIT BREAKER?","options":["ONCE.","ONCE, IF AUTHORIZED BY THE PROCEDURES.","TWICE.","TWICE, IF AUTHORIZED BY THE PROCEDURES."],"correct":1,"explanation":"En vuelo, un C/B que saltó solo no se vuelve a meter, salvo que el comandante lo considere necesario para seguir el vuelo con seguridad; y en ese caso, una sola vez.","taughtIn":["ele-8-c5"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:113r3yv"}}]},{"id":"ele-9","subject":"electrico","order":9,"kind":"lesson","level":3,"ident":"CSM","title":"Emergencia: el RAT y el EMER GEN","goal":"Explicar cuándo sale el RAT, cómo mueve el emergency generator, qué alimenta y qué cuidar en ELEC EMER CONFIG.","intro":"Hoy, la emergencia eléctrica: cuando no queda ningún generador principal.","minutes":6,"cards":[{"id":"ele-9-c1","title":"Cuándo sale el RAT","body":"Si se pierden **AC BUS 1 y AC BUS 2** con el avión sobre **100 kt**, el RAT sale solo.\n\nTambién se puede sacar a mano con el **EMER ELEC PWR MAN ON** pb (o con el RAT MAN ON del panel HYD). La falla de un solo generador no lo saca: para eso están el APU GEN y el BUS TIE.","diagram":{"alt":"Sin AC BUS 1 ni AC BUS 2 y sobre 100 kt, o con MAN ON, sale el RAT. El RAT presuriza el Blue, que mueve el motor hidráulico del EMER GEN; el EMER GEN alimenta AC ESS BUS y, por el ESS TR, DC ESS BUS.","src":"assets/estaciones/diagramas/ele-emer-logica.svg"},"keyIdea":"RAT automático: sin AC BUS 1 ni 2 y sobre 100 kt. Manual: MAN ON."},{"id":"ele-9-c2","title":"Del viento a la electricidad","body":"El RAT no está unido al generador. La cadena es:\n- el viento hace girar el RAT;\n- el RAT presuriza el hidráulico **Blue**;\n- el Blue mueve un motor hidráulico que hace girar el **emergency generator** (5 KVA).\n\nEl generador se conecta a la red 3 s después de que el RAT empieza a alimentarlo.","keyIdea":"Viento → RAT → Blue → motor hidráulico → EMER GEN."},{"id":"ele-9-c3","title":"Los segundos del medio","body":"Entre que sale el RAT y se acopla el generador pasan cerca de **8 s**. Mientras tanto, las **baterías** alimentan la red de emergencia.\n\nEn ese lapso se enciende en rojo la luz **FAULT** del RAT & EMER GEN: avisa que el emergency generator todavía no alimenta, con AC BUS 1 y AC BUS 2 sin energía.","keyIdea":"Unos 8 s con baterías; FAULT rojo: el EMER GEN aún no alimenta."},{"id":"ele-9-c4","title":"Qué alimenta el EMER GEN","body":"Con el emergency generator funcionando:\n- alimenta el **AC ESS BUS** y el **AC ESS SHED BUS**;\n- a través del **ESS TR**, alimenta el **DC ESS BUS** y el **DC ESS SHED BUS**;\n- los **HOT BUS** siguen con las baterías.\n\nEl resto de la red (AC BUS 1 y 2, DC BUS 1 y 2, DC BAT BUS) queda sin energía.","diagram":{"alt":"Página ELEC con el EMER GEN funcionando: AC 1, AC 2, DC 1, DC 2, DC BAT y los TR principales sin energía; el EMER GEN alimenta AC ESS y, por el ESS TR, DC ESS.","src":"assets/estaciones/diagramas/ele-ecam-emer.svg"},"keyIdea":"EMER GEN: AC ESS (y su SHED) y, por el ESS TR, DC ESS (y su SHED)."},{"id":"ele-9-c5","title":"ELEC EMER CONFIG","body":"En esta configuración queda lo esencial. Lo que hay que cuidar:\n- **velocidad mínima del RAT: 140 kt**. El RAT alimenta el generador hasta unos 125 kt, pero a esas velocidades puede no lograrlo en el flare;\n- los motores reciben combustible **solo por gravedad** (gravity feed): evitar G negativas;\n- radios limitadas: solo VHF 1, HF 1 y ATC 1.","keyIdea":"ELEC EMER CONFIG: mínimo 140 kt, gravity feed (sin G negativas) y equipos limitados."}],"test":[{"id":"ele-9-t1","type":"mcq","question":"¿Qué condiciones producen el despliegue automático del RAT desde el punto de vista eléctrico?","options":["Pérdida de un solo AC BUS, sin condición de velocidad","AC BUS 1+2 sin alimentación y velocidad >100 kt","Pérdida de DC BUS 1 y velocidad superior a 50 kt","Cualquier falla de un engine generator"],"correct":1,"explanation":"El RAT es una respuesta a la pérdida de la generación AC principal, no a una falla aislada. La condición de velocidad asegura que exista energía aerodinámica suficiente para que el RAT pueda accionar el sistema de emergencia.","taughtIn":["ele-9-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:52qk48"}},{"id":"ele-9-t2","type":"mcq","question":"¿Cómo llega la energía del RAT al emergency generator?","options":["El RAT está acoplado mecánicamente directamente al generador","RAT presuriza Blue; Blue acciona el emergency generator","El RAT carga BAT 1 y BAT 1 alimenta el generador","A través de la PTU hacia el sistema Green"],"correct":1,"explanation":"La cadena es aerodinámica → hidráulica → eléctrica: el RAT mantiene el Blue hydraulic system y ese sistema acciona el emergency generator. Por eso no es correcto imaginar un eje directo RAT-generador.","taughtIn":["ele-9-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1ya6nzn"}},{"id":"ele-9-t3","type":"mcq","question":"¿Quién sostiene la emergency generation network mientras se extiende el RAT y se acopla el emergency generator?","options":["El APU","Las baterías","GEN 1","El DC BUS"],"correct":1,"explanation":"Existe un intervalo entre la pérdida de los buses principales y la estabilización del emergency generator. Durante ese lapso las baterías hacen de puente para que la red esencial no desaparezca.","taughtIn":["ele-9-c3"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:tw33e2"}},{"id":"ele-9-t4","type":"mcq","question":"IN CRUISE, YOU HAVE SUDDENLY A MASTER WARNING AND CAUTION COMES ON WITH ELEC EMER CONFIG AND APP OFF. YOU NOTICE A RED FAULT LIGHT ON THE RAT & EMER GEN PUSHBUTTON. WHAT DO YOU THINK OF THIS INDICATION?","options":["THE EMER GEN IS NOT YET SUPPLYING THE SYSTEM.","THE RAT HAS FAILED. YOU WILL HAVE TO TURN THE BATTERIES TO OFF.","THE FAULT LIGHT IS ALWAYS ON WHEN ARE IN SLEC EMER CONFIG.","THE RAT HAS FAILED. YOU HAVE TO TRY TO RECONNECT BOTH IDC/S."],"correct":0,"explanation":"Esta indicación refleja que el emergency generator todavía no está suministrando al sistema, una condición transitoria mientras el RAT termina de extenderse y el generador se estabiliza, no necesariamente una falla del RAT que exija reconectar los IDG.","taughtIn":["ele-9-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:11vgyxv"}},{"id":"ele-9-t5","type":"mcq","question":"Una vez acoplado el emergency generator, ¿qué buses esenciales alimenta directamente/mediante ESS TR?","options":["AC BUS 1; DC BUS 1 mediante TR 1","AC ESS BUS; DC ESS BUS vía ESS TR","AC ESS SHED; DC BAT BUS vía BAT 1","AC BUS 2; DC BUS 2 mediante TR 2"],"correct":1,"explanation":"La emergencia busca conservar la red esencial, no restaurar todos los buses normales. El emergency generator entrega AC ESS y, mediante el ESS TR, mantiene DC ESS.","taughtIn":["ele-9-c4"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:bq7ol6"}},{"id":"ele-9-t6","type":"mcq","question":"WHICH OF THE FOLLOWING AC BUSES CAN BE POWERED BY THE EMERGENCY GENERATOR?","options":["AC BUS 1.","AC BUS 2.","AC ESS BUS / AC ESS SHED BUS."],"correct":2,"explanation":"El emergency generator puede alimentar el AC ESS BUS y el AC ESS SHED BUS, no los AC BUS 1 o 2 principales, que dependen de fuentes normales (motor, externa o APU).","taughtIn":["ele-9-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:19pc7gb"}}]},{"id":"ele-10","subject":"electrico","order":10,"kind":"lesson","level":3,"ident":"INV","title":"Solo baterías: el static inverter","goal":"Explicar qué queda cuando no hay ningún generador, ni siquiera el EMER GEN, y qué cambia con la velocidad.","intro":"Última clase del eléctrico: cuando solo quedan las baterías.","minutes":5,"cards":[{"id":"ele-10-c1","title":"Si el RAT se detiene","body":"Si el RAT pierde velocidad y se detiene (stall), el Blue pierde presión y el emergency generator deja de alimentar.\n\nLa red de emergencia pasa sola a las **baterías y al static inverter**, y se cortan las barras **AC ESS SHED** y **DC ESS SHED**.","diagram":{"alt":"Solo baterías: BAT 1 alimenta el STAT INV, que alimenta AC STAT INV BUS y, sobre 50 kt, AC ESS BUS; BAT 2 alimenta DC ESS BUS; las barras SHED se cortan. En tierra, bajo 100 kt el DC BAT BUS se conecta a las baterías y bajo 50 kt se corta AC ESS.","src":"assets/estaciones/diagramas/ele-solo-baterias.svg"},"keyIdea":"RAT en stall: baterías y static inverter, y se cortan las barras SHED."},{"id":"ele-10-c2","title":"Cada batería, su tarea","body":"Sin generadores ni EMER GEN:\n- la **BAT 1** alimenta el **static inverter**, que entrega AC al **AC STAT INV BUS** y, si el avión va a más de **50 kt**, también al **AC ESS BUS**;\n- la **BAT 2** alimenta el **DC ESS BUS**.","more":"Sobre 50 kt, el static inverter se activa solo cuando únicamente las baterías alimentan el avión, sin importar la posición de los BAT pb. Bajo 50 kt, además necesita los dos BAT pb en AUTO.","keyIdea":"BAT 1 → static inverter → AC STAT INV BUS y AC ESS BUS (sobre 50 kt). BAT 2 → DC ESS BUS."},{"id":"ele-10-c3","title":"Para qué sirven las barras SHED","body":"Las barras **SHED** (AC ESS SHED y DC ESS SHED) agrupan equipos esenciales que se pueden sacrificar.\n\nCon el EMER GEN tienen energía, pero con baterías solas **nunca**: cortarlas reduce el consumo y hace durar más las baterías.","keyIdea":"Con baterías solas, las barras SHED nunca tienen energía: así se ahorra batería."},{"id":"ele-10-c4","title":"En tierra: bajo 100 y bajo 50 kt","body":"Al aterrizar en esta configuración, la velocidad cambia la red:\n- bajo **100 kt**, el DC BAT BUS se conecta solo a las baterías;\n- bajo **50 kt**, se corta el AC ESS BUS y se pierden **todas las pantallas**.\n\nAdemás, en tierra y solo con baterías, el APU se puede arrancar recién bajo 100 kt.","keyIdea":"En tierra: bajo 100 kt, DC BAT BUS a las baterías; bajo 50 kt, sin AC ESS ni pantallas."}],"test":[{"id":"ele-10-t1","type":"mcq","question":"Si el RAT se detiene y el emergency generator deja de producir, ¿qué hace automáticamente la red de emergencia?","options":["Desenergiza por completo los buses esenciales y deja solo los hot battery buses","Transfiere a batteries/static inverter y elimina cargas de los ESS SHED buses","Conecta GEN 1 en paralelo con BAT 1 para mantener ambos AC buses energizados","Mantiene todos los buses esenciales y shed alimentados directamente por baterías"],"correct":1,"explanation":"Con energía almacenada limitada, la lógica conserva únicamente las cargas esenciales. El static inverter permite mantener la alimentación AC necesaria y se eliminan los shed buses para reducir consumo.","taughtIn":["ele-10-c1"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:j6k4ya"}},{"id":"ele-10-t2","type":"mcq","question":"Sin AC BUS 1/2 ni EMER GEN, y con velocidad superior a 50 kt, ¿qué puede alimentar BAT 1 además del AC STAT INV BUS?","options":["El AC ESS BUS","AC BUS 2 directo","DC ESS BUS","APU starter"],"correct":0,"explanation":"BAT 1 alimenta el static inverter y, por encima de 50 kt en esta condición, permite sostener también el AC ESS BUS. BAT 2 tiene otra función esencial en DC.","taughtIn":["ele-10-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:g09t4p"}},{"id":"ele-10-t3","type":"mcq","question":"En esa misma condición sin generación AC ni EMER GEN, ¿qué bus esencial alimenta BAT 2?","options":["DC ESS BUS","AC ESS BUS","AC BUS 1 completo","AC STAT INV BUS"],"correct":0,"explanation":"La división de funciones conserva redes esenciales diferentes: BAT 1 participa en la generación AC mediante el static inverter y BAT 2 mantiene DC ESS.","taughtIn":["ele-10-c2"],"source":{"bank":"fcom","system":"electrical","appId":"electrical:1qi7zq0"}},{"id":"ele-10-t4","type":"mcq","question":"WHEN ARE THE ESSENTIAL SHEED BUSES POWERED BY HIS BATTERY?","options":["NEVER. THE PURPOSE OF THE SHED BUSES IS TO REDUCE THE LOAD ON THE BATTERIES.","IN CASE OF DOUBLE GENERATOR FAILURE.","AFTER EVERY IDG CONNECTION."],"correct":0,"explanation":"Nunca: el propósito de los shed buses es justamente reducir la carga sobre las baterías, por lo que quedan deliberadamente sin alimentar cuando el sistema depende de ellas.","taughtIn":["ele-10-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1p974ko"}},{"id":"ele-10-t5","type":"mcq","question":"AFTER LANDING, IN THE EMERGENCY ELECTRICAL CONFIGURATION: THE BATTERIES AUTOMATICALLY CONNECT TO THE DC BAT BUS WHEN SPEED DECREASES BELOW _____ KNOTS.","options":["50","70","90","100"],"correct":3,"explanation":"En configuración eléctrica de emergencia, las baterías se reconectan automáticamente al DC BAT BUS al bajar de 100 kt de velocidad.","taughtIn":["ele-10-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:oiydvv"}}]},{"id":"ele-repaso","subject":"electrico","order":11,"kind":"review","level":3,"ident":"REL","title":"Repaso del eléctrico","goal":"Comprobar que recuerdas toda la red eléctrica, con preguntas planteadas de otra forma.","intro":"Repaso general: las mismas ideas, preguntadas de otra forma. Al final, explícame la red y la emergencia con tu voz.","minutes":7,"cards":[{"id":"ele-repaso-c1","title":"Toda la red en una mirada","body":"Antes de empezar, repasa el esquema: las fuentes abajo, las barras AC y DC, el BUS TIE, las baterías con sus HOT BUS y los respaldos (ESS TR, static inverter y EMER GEN).","diagram":{"alt":"Esquema de la red eléctrica del A320 en configuración normal, con sus fuentes, barras y respaldos.","src":"assets/estaciones/diagramas/ele-arquitectura.svg"},"keyIdea":"Fuentes, barras AC y DC, BUS TIE, baterías y respaldos."}],"test":[{"id":"ele-repaso-t1","type":"mcq","question":"THE NORMAL PRIORITY FOR SUPPLYING ELECTRICAL POWER TO THE AC BUSES IS:","options":["EXTERNAL POWER, ENGINE GENERATORS, APU.","APU, EXTERNAL POWER, ENGINE GENERATORS.","ENGINE GENERATORS, EXTERNAL POWER, APU."],"correct":2,"explanation":"La prioridad normal es: generadores de motor primero, energía externa en segundo lugar, y el generador del APU al final.","taughtIn":["ele-3-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:49pf86"}},{"id":"ele-repaso-t2","type":"mcq","question":"ENGINE #L HAS JUST BEEN STARTED AND THE APU IS INOPERATIVE. THE EXT PWR PUSH BUTTON BLUE ON LIGHT IS ILLUMINATED. WHICH OF THE STATEMENTS BELOW IS CORRECT?","options":["EXTERNAL POWER IS SUPPLYING AIL ELECTRICAL NEEDS.","ENGINE GEN #L IS SUPPLYING AC BUS #L AND THE DOWNSTREAM SYSTEMS, AND AC BUS #2 THROUGH THE BUS TIE CONTACTORS.","GEN #I SUPPLIES AC BUS #I AND (GENERALLY) THE DOWNSTREAM SYSTEMS; EXT POWER SUPPLIES AC BUS #2 ."],"correct":2,"explanation":"El generador del motor 1 alimenta el AC BUS 1 y en general sus sistemas asociados, mientras que la energía externa (ya conectada, luz azul ON) alimenta el AC BUS 2, cada fuente manteniendo su propio lado en vez de mezclarse.","taughtIn":["ele-3-c1","ele-3-c4","ele-4-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:70xm0w"}},{"id":"ele-repaso-t3","type":"mcq","question":"IF DURING A NORMAL FLIGHT THE BUS TIE PUSH BUTTON IS DEPRESSED TO OFF, WHAT EFFECT WOULD THIS HAVE ON POWER TO THE BUSES?","options":["NONE.","ALL POWER WOULD BE LOST AND THE AIRCRAFT WOULD BE POWERED BY THE BATTERIES UNTIL THE RAT WAS UP TO SPEED.","THE POWER TRANSFER WOULD SWITCH TO THE OPPOSITE BUS.","THIS IS NOT POSSIBLE AS THE BUS TIE CONTACTORS ARE LOCKED OUT DURING FLIGHT."],"correct":0,"explanation":"En vuelo normal, con ambos generadores de motor sanos alimentando cada uno su propio lado, los contactores de bus tie ya están abiertos por defecto; seleccionar el pushbutton a OFF no tiene ningún efecto observable en esa condición.","taughtIn":["ele-3-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:115c1z2"}},{"id":"ele-repaso-t4","type":"mcq","question":"THE AC ESSENTIAL BUS IS POWERED BY THE BATTERY AT SPEED ABOVE 50 KT.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: en un escenario de pérdida eléctrica total, por encima de 50 kt las baterías (a través del inversor estático) sostienen el AC ESS BUS; por debajo de 50 kt ese bus se desprende para preservar la energía de la batería.","taughtIn":["ele-10-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1xyzncm"}},{"id":"ele-repaso-t5","type":"mcq","question":"WHEN NO OTHER POWER IS AVAILABLE IN FLIGHT, THE STATIC INVERTER CONVERTS POWER TO AC POWER FOR THE ____ BUS, AND _____ POWERS THE _____ BUS.","options":["BAT1 DC /AC ESS BUS /BAT2 /DC ESS.","BAT1 DC / AC ESS SHED /BAT2 /DC ESS SHED.","BAT1 DC / AC ESS BUS /BAT2 /DC ESS SHED."],"correct":0,"explanation":"El inversor estático toma DC de BAT1 y lo convierte en AC para alimentar el AC ESS BUS, mientras que BAT2 alimenta directamente el DC ESS BUS.","taughtIn":["ele-10-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:140bvq4"}},{"id":"ele-repaso-t6","type":"oral","question":"Observa el diagrama de arquitectura eléctrica y explica: qué alimenta normalmente las barras AC y DC, qué queda conectado permanentemente a las baterías, y qué respalda al sistema si se pierden ambos generadores de motor.","image":{"alt":"Esquema de la red eléctrica del A320.","src":"assets/estaciones/diagramas/ele-arquitectura.svg"},"reference":"En operación normal, GEN 1 y GEN 2, accionados por los motores, alimentan AC BUS 1 y AC BUS 2 a través de sus contactores de línea; el APU GEN o el EXT PWR pueden reemplazar a cualquiera de los generadores de motor, y un BUS TIE CONT permite compartir la alimentación entre ambas barras AC. Del lado DC, TR 1 y TR 2 convierten AC a DC para alimentar DC BUS 1 y DC BUS 2. Las baterías, BAT 1 y BAT 2, quedan permanentemente conectadas a su HOT BUS incluso con todo apagado, y se conectan a la DC BAT BUS a través de su BAT CONT para cargarse o para respaldar la red esencial. Si se pierden ambos generadores de motor, el EMER GEN, accionado por el circuito hidráulico azul, alimenta la AC ESS BUS, que a su vez energiza el ESS TR para mantener la DC ESS BUS; y si tampoco hay EMER GEN disponible, un inversor estático (STAT INV) puede transformar DC de las baterías en AC para seguir alimentando la red esencial.","concepts":[{"label":"GEN 1 y GEN 2 (motor) alimentan AC BUS 1/2 normalmente","weight":2,"required":true,"accepted":["gen 1","gen 2","generadores de motor","dos generadores","cada motor","gen line cont"]},{"label":"APU GEN o EXT PWR pueden reemplazar a los generadores de motor","weight":2,"accepted":["apu gen","poder externo","external power","ext pwr","reemplazar","generador de la apu"]},{"label":"BUS TIE conecta AC BUS 1 y AC BUS 2","weight":1,"accepted":["bus tie","conecta las dos barras","comparten alimentacion","interconecta ac bus"]},{"label":"TR 1 y TR 2 convierten AC a DC para DC BUS 1/2","weight":2,"required":true,"accepted":["tr 1","tr 2","transformador rectificador","convierten","convierte ac a dc","rectifica"]},{"label":"Baterías conectadas permanentemente a HOT BUS","weight":2,"required":true,"accepted":["hot bus","barra caliente","conectadas permanentemente","siempre conectadas","con todo apagado"]},{"label":"Pérdida de ambos generadores de motor: EMER GEN (circuito azul) alimenta la red esencial","weight":2,"required":true,"accepted":["emer gen","generador de emergencia","circuito azul","hidraulico azul","ambos generadores","red esencial","ac ess"]},{"label":"STAT INV: respaldo final (batería a AC) si tampoco hay EMER GEN","weight":1,"accepted":["stat inv","inversor estatico","static inverter","bateria a ac","invierte dc a ac"]}],"criticalErrors":[{"accepted":["las baterias solo se conectan si fallan los generadores","las baterias estan desconectadas en operacion normal","las baterias no hacen nada mientras haya generadores"],"penalty":3,"feedback":"Las baterías quedan conectadas permanentemente a su HOT BUS incluso con todo apagado; no es algo que se active recién cuando fallan los generadores."}],"taughtIn":["ele-1-c2","ele-1-c3","ele-1-c5","ele-2-c1","ele-2-c3","ele-3-c4","ele-6-c1","ele-9-c2","ele-10-c2"],"source":{"bank":"oral","id":"ov_elec_arch"}},{"id":"ele-repaso-t7","type":"oral","question":"Si terminas en ELEC EMER CONFIG, ¿qué esperarías tener disponible y qué deberías extremar?","reference":"Esperaría contar con el RAT desplegado alimentando la red esencial a través del emergency generator, con equipos de radio y navegación limitados. Por separado, en esa configuración también hay FUEL GRVTY FEED sin bombas, así que hay que evitar G negativas, y hay que evitar volar por debajo de la velocidad mínima recomendada para no hacer stall al RAT (dos riesgos distintos, no la misma causa).","concepts":[{"label":"RAT desplegado / emergency generator","weight":2,"required":true,"accepted":["rat","ram air turbine","emergency generator","generador de emergencia"]},{"label":"Equipos limitados (radio/nav)","weight":2,"accepted":["equipos limitados","radio limitado","navegacion limitada","equipos de radio","radio y navegacion","un solo","solo queda un"]},{"label":"Fuel gravity feed sin bombas: evitar G negativas","weight":1,"accepted":["gravity feed","sin bombas","alimentacion por gravedad","g negativas"]},{"label":"Evitar velocidad baja para no hacer stall al RAT","weight":2,"accepted":["velocidad minima","no bajar de","evitar stall del rat","stall al rat","140 kt","velocidad minima del rat","ciento cuarenta nudos"]}],"taughtIn":["ele-9-c1","ele-9-c4","ele-9-c5"],"source":{"bank":"oral","id":"ov_elec_emer"}}]}]},{"id":"hidraulico","title":"Hidráulico","color":"#2F6FD6","stations":[{"id":"hid-1","subject":"hidraulico","order":1,"kind":"lesson","level":1,"ident":"HYD","title":"Tres sistemas independientes","goal":"Explicar cuántos sistemas hidráulicos tiene el A320, a qué presión trabajan y qué bomba presuriza cada uno.","intro":"Partimos por lo básico: tres sistemas, tres colores. Cinco fichas y después me lo explicas tú.","minutes":6,"cards":[{"id":"hid-1-c1","title":"¿Para qué sirve la hidráulica?","body":"En el A320, la hidráulica mueve todo lo que necesita mucha fuerza: las superficies de los flight controls, el tren de aterrizaje, los frenos, los flaps y slats y los reversers.\n\nUna bomba empuja el fluido a alta presión por las cañerías hasta un actuador, que transforma esa presión en movimiento.","keyIdea":"La hidráulica da la fuerza para mover superficies, tren, frenos, flaps, slats y reversers."},{"id":"hid-1-c2","title":"Tres sistemas, tres colores","body":"El avión tiene tres sistemas hidráulicos que funcionan todo el tiempo: **Green**, **Blue** y **Yellow**. Cada uno tiene su propio reservorio, y el fluido no puede pasar de un sistema a otro.\n\nPor eso, si un sistema pierde su fluido por una fuga, los otros dos siguen trabajando.","example":"Piensa en tres circuitos de agua separados, cada uno con su estanque y su bomba: una fuga en uno no vacía a los otros.","keyIdea":"Tres sistemas independientes: el fluido nunca pasa de uno a otro."},{"id":"hid-1-c3","title":"3000 PSI","body":"Los tres sistemas trabajan normalmente a **3000 PSI**.\n\nLa excepción es el Blue cuando lo mueve el RAT, la turbina de emergencia: la turbina entrega menos potencia y el sistema trabaja a **2500 PSI**.","keyIdea":"3000 PSI normal; 2500 PSI cuando el RAT mueve el Blue."},{"id":"hid-1-c4","title":"¿Quién presuriza cada sistema?","body":"En operación normal, cada sistema tiene su bomba:\n- **Green:** una bomba movida por el motor 1.\n- **Yellow:** una bomba movida por el motor 2.\n- **Blue:** una bomba eléctrica.\n\nO sea, dos engine-driven pumps y una electric pump. El Blue es el único que no depende de un motor.","diagram":{"alt":"Esquema de los tres sistemas hidráulicos con sus bombas, sus reservorios y la PTU entre Green y Yellow.","src":"assets/estaciones/diagramas/hid-arquitectura.svg"},"keyIdea":"Motor 1 → Green, motor 2 → Yellow, bomba eléctrica → Blue."},{"id":"hid-1-c5","title":"Los respaldos","body":"Además, cada sistema tiene respaldos:\n- **Blue:** el RAT, en emergencia.\n- **Yellow:** una bomba eléctrica, que permite usarlo en tierra con los motores apagados, y una hand pump para las cargo doors.\n- **Green y Yellow:** la PTU, que permite que uno ayude al otro.\n\nCada uno tiene su propia estación más adelante.","keyIdea":"Blue: elec pump y RAT. Yellow: ENG 2 pump, elec pump y hand pump. Entre Green y Yellow, la PTU."}],"test":[{"id":"hid-1-t1","type":"mcq","question":"¿Cuál es la presión normal de operación de los sistemas hidráulicos del A320?","options":["3000 PSI en los tres sistemas por igual","2800 PSI; Blue con RAT: 2200 PSI","3000 PSI; Blue con RAT: 2500 PSI","3200 PSI; Blue con RAT: 2700 PSI"],"correct":2,"explanation":"Los tres sistemas (verde, azul y amarillo) trabajan normalmente a 3000 PSI. Ese valor baja a 2500 PSI únicamente cuando el sistema azul es alimentado por el RAT, que tiene menor capacidad.","taughtIn":["hid-1-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1g9pzwb"}},{"id":"hid-1-t2","type":"mcq","question":"¿Es posible transferir fluido hidráulico de un sistema a otro?","options":["Sí, de forma continua entre los tres sistemas","Sí, pero solo mediante la PTU y en tierra","No, el fluido no puede transferirse entre sistemas","Sí, únicamente entre azul y amarillo mediante válvulas de emergencia"],"correct":2,"explanation":"El fluido hidráulico no puede pasar de un sistema a otro: cada sistema tiene su propio reservorio. La PTU transfiere potencia entre Green y Yellow, nunca fluido.","taughtIn":["hid-1-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1x4s4z"}},{"id":"hid-1-t3","type":"mcq","question":"¿Qué presuriza el sistema verde en operación normal?","options":["Una bomba eléctrica de respaldo permanente","Una bomba accionada por el motor 1","El generador APU en tierra","Un acumulador de nitrógeno de alta presión"],"correct":1,"explanation":"En operación normal, una bomba accionada por ENG 1 presuriza el sistema Green. Esa es su fuente normal de presión.","taughtIn":["hid-1-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1jtvp82"}},{"id":"hid-1-t4","type":"mcq","question":"¿Qué dos fuentes pueden presurizar el sistema azul?","options":["Motor 1 y motor 2","Electric pump y RAT","PTU y hand pump","Bomba manual y APU"],"correct":1,"explanation":"El sistema azul es el único de los tres que no depende directamente de un motor: en operación normal lo mueve una bomba eléctrica, y en una emergencia total (RAT desplegado) pasa a ser accionado por el propio RAT, lo que lo hace clave para mantener control mínimo de la aeronave.","taughtIn":["hid-1-c4","hid-1-c5"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1jtlrvt"}},{"id":"hid-1-t5","type":"mcq","question":"En la arquitectura hidráulica normal, ¿qué combinación de bombas mantiene presurizados los tres sistemas?","options":["Una engine-driven pump en Green, una en Yellow y una electric pump en Blue","Dos electric pumps para Green/Yellow y la PTU como fuente normal del Blue","Una engine-driven pump para Green, y electric pumps como fuente normal de Yellow y Blue","Dos engine-driven pumps alimentan los tres sistemas mediante válvulas de transferencia"],"correct":0,"explanation":"La arquitectura normal mantiene independencia entre sistemas: Green usa la bomba del motor 1, Yellow la del motor 2 y Blue una bomba eléctrica. La PTU es respaldo de potencia entre Green y Yellow, no una bomba normal del Blue.","taughtIn":["hid-1-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:11lcxfr"}}]},{"id":"hid-2","subject":"hidraulico","order":2,"kind":"lesson","level":1,"ident":"PTU","title":"La PTU","goal":"Explicar qué hace la PTU, cuándo entra en acción y por qué no mezcla fluido.","intro":"Hoy toca la pieza más curiosa del hidráulico: la PTU. Cinco fichas y después la prueba.","minutes":5,"cards":[{"id":"hid-2-c1","title":"Un puente entre Green y Yellow","body":"La **PTU** (Power Transfer Unit) une el Green con el Yellow. Si uno de los dos pierde presión, el otro le presta potencia.\n\nEs bidireccional: el Yellow puede presurizar al Green, y el Green al Yellow.","keyIdea":"La PTU une Green y Yellow, y funciona en ambos sentidos."},{"id":"hid-2-c2","title":"Pasa potencia, no fluido","body":"Por dentro son dos unidades hidráulicas unidas por un eje. El sistema con presión hace girar su unidad, que trabaja como motor. El eje hace girar la otra unidad, que trabaja como bomba y presuriza el otro sistema.\n\nLo que cruza es potencia: cada fluido se queda en su propio sistema.","example":"Como dos ruedas en un mismo eje: si giras una, gira la otra, pero cada una sigue en su lado.","diagram":{"alt":"Dos unidades hidráulicas unidas por un eje: la del Yellow gira como motor y hace girar la del Green, que trabaja como bomba.","src":"assets/estaciones/diagramas/hid-ptu.svg"},"keyIdea":"La PTU transfiere potencia mecánica-hidráulica; los fluidos nunca se mezclan."},{"id":"hid-2-c3","title":"¿Cuándo actúa?","body":"Con el PTU pb en AUTO, la PTU trabaja sola: entra en acción cuando la diferencia de presión entre el Green y el Yellow supera **500 PSI**. Nadie tiene que encenderla.","example":"Si falla la bomba del motor 2, el Yellow pierde presión. Apenas la diferencia con el Green supera 500 PSI, la PTU empieza a presurizar el Yellow con la potencia del Green.","keyIdea":"Actúa automáticamente cuando la diferencia entre Green y Yellow supera 500 PSI."},{"id":"hid-2-c4","title":"En tierra, sin motores","body":"Con los motores apagados, la bomba eléctrica del Yellow puede presurizar el Yellow, y a través de la PTU también el Green.\n\nAsí se puede tener Green en tierra sin encender motores.","keyIdea":"Con la Yellow elec pump y la PTU hay Green en tierra sin motores."},{"id":"hid-2-c5","title":"Primer y segundo arranque","body":"Durante el arranque del primer motor, la PTU queda inhibida.\n\nDurante el arranque del segundo motor, el sistema la prueba automáticamente.","more":"La inhibición viene de una lógica de tierra. Con un master lever en ON y el otro en OFF, la PTU solo funciona si el parking brake está suelto y la NWS no está en posición de remolque (towing). Como el primer motor normalmente se arranca con el parking brake puesto, la PTU queda inhibida.\n\nCon los dos master levers en OFF, o los dos en ON, la PTU funciona aunque el parking brake esté puesto.","keyIdea":"Inhibida en el primer engine start; probada automáticamente en el segundo."}],"test":[{"id":"hid-2-t1","type":"mcq","question":"¿A partir de qué diferencial de presión entre el sistema verde y el amarillo entra en acción automáticamente la PTU?","options":["300 PSI de diferencial","500 PSI de diferencial","800 PSI de diferencial","1000 PSI de diferencial"],"correct":1,"explanation":"La PTU actúa como respaldo automático: apenas detecta que un sistema (verde o amarillo) tiene 500 PSI menos de presión que el otro, se activa para equilibrar la potencia entre ambos sin que la tripulación intervenga.","taughtIn":["hid-2-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:106iugc"}},{"id":"hid-2-t2","type":"mcq","question":"¿Qué es correcto sobre la Power Transfer Unit (PTU)?","options":["Transfiere fluido hidráulico entre Green y Yellow para igualar cantidades","Es bidireccional y transfiere potencia entre Green y Yellow, no fluido","Solo permite que Yellow presurice Green y nunca funciona en sentido contrario","Solo opera cuando APU está running y ambos engine-driven pumps están detenidos"],"correct":1,"explanation":"La PTU es esencialmente una bomba hidráulica movida por otra bomba hidráulica: usa la presión de un sistema para mover una unidad que presuriza el otro. Funciona en ambos sentidos según cuál de los dos (verde o amarillo) tenga menor presión en cada momento.","taughtIn":["hid-2-c1","hid-2-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:wxjsp5"}},{"id":"hid-2-t3","type":"mcq","question":"¿Cuándo está inhibida la PTU y cuándo se prueba automáticamente?","options":["Se inhibe durante el primer engine start y se prueba durante el segundo","Se inhibe durante ambos engine starts y se prueba después del taxi","Se mantiene disponible durante ambos starts y se prueba antes del primero","Se inhibe durante el segundo start y se prueba durante el primero"],"correct":0,"explanation":"La PTU se inhibe durante el primer engine start y se prueba automáticamente durante el segundo engine start.","taughtIn":["hid-2-c5"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1rx3pif"}},{"id":"hid-2-t4","type":"mcq","question":"La PTU está funcionando y aumenta la presión del sistema Green. ¿Qué está transfiriendo realmente desde Yellow?","options":["Potencia mecánico-hidráulica, sin mezclar el fluido de ambos sistemas","Fluido hidráulico Yellow hacia el reservoir Green hasta igualar cantidades","Presión neumática de los reservoirs para elevar la presión Green","Energía eléctrica de la Yellow electric pump hacia la Green engine pump"],"correct":0,"explanation":"La PTU conecta los sistemas únicamente desde el punto de vista de potencia. Sus dos unidades hidráulicas están acopladas mecánicamente, por lo que una puede impulsar a la otra sin que el fluido de Green y Yellow se mezcle.","taughtIn":["hid-2-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:yu9ict"}}]},{"id":"hid-3","subject":"hidraulico","order":3,"kind":"lesson","level":2,"ident":"RAT","title":"El Blue y el RAT","goal":"Explicar cómo funciona el Blue, cuándo sale el RAT y cómo se controla.","intro":"Hoy, el Blue: el sistema que no depende de ningún motor, y su as bajo la manga, el RAT.","minutes":6,"cards":[{"id":"hid-3-c1","title":"El Blue funciona con electricidad","body":"El Blue es el único sistema sin bomba de motor: lo presuriza una bomba eléctrica.\n\nCon el BLUE ELEC PUMP pb en AUTO y AC power disponible, la bomba funciona:\n- siempre en vuelo;\n- en tierra, si hay al menos un motor en marcha.","keyIdea":"Blue elec pump en AUTO: siempre en vuelo; en tierra, con un motor en marcha."},{"id":"hid-3-c2","title":"BLUE PUMP OVRD","body":"¿Y en tierra sin motores? En el maintenance panel está el **BLUE PUMP OVRD** pb: enciende la bomba eléctrica del Blue en tierra, siempre que el BLUE ELEC PUMP pb del panel HYD esté en AUTO.\n\nEs un control de mantenimiento, por ejemplo para pruebas en tierra.","keyIdea":"BLUE PUMP OVRD enciende la bomba del Blue en tierra, con el BLUE ELEC PUMP pb en AUTO."},{"id":"hid-3-c3","title":"El RAT","body":"El **RAT** (Ram Air Turbine) es una turbina que baja desde el fuselaje y gira con el viento relativo. Mueve una bomba hidráulica que presuriza el Blue a 2500 PSI.\n\nAsí queda hidráulica aunque se pierda la energía eléctrica o fallen los dos motores.","diagram":{"alt":"A320 visto desde abajo con el RAT desplegado bajo el fuselaje; un círculo amplía la turbina.","src":"assets/estaciones/imagenes/hid-rat-avion.webp"},"keyIdea":"El RAT mueve una bomba que presuriza el Blue a 2500 PSI."},{"id":"hid-3-c4","title":"¿Cuándo sale?","body":"Sale solo cuando se pierden al mismo tiempo **AC BUS 1 y AC BUS 2** con el avión sobre **100 kt**.\n\nUna falla que es solo hidráulica no lo saca. Si hace falta, la tripulación lo despliega con el **RAT MAN ON** pb, que funciona en cualquier momento.","example":"En una falla eléctrica en vuelo que deja sin energía AC BUS 1 y AC BUS 2, el RAT sale solo, sin que nadie lo pida.","more":"El Blue presurizado por el RAT también mueve el emergency generator, que alimenta las barras esenciales.\n\nSi el RAT pierde velocidad y se detiene (stall), el Blue se queda sin presión, el emergency generator deja de alimentar y la energía pasa a las baterías. Lo verás en Eléctrico.","diagram":{"alt":"El RAT mueve el Blue a 2500 PSI y el Blue mueve el emergency generator. Reglas: sale solo sin AC BUS 1 ni AC BUS 2 sobre 100 kt, manual con RAT MAN ON, stow solo en tierra.","src":"assets/estaciones/diagramas/hid-rat-reglas.svg"},"keyIdea":"Automático: se pierden AC BUS 1 y 2 sobre 100 kt. Manual: RAT MAN ON, en cualquier momento."},{"id":"hid-3-c5","title":"Una vez afuera","body":"Una vez desplegado, el RAT se queda afuera: solo se puede stow (guardar) con el avión en tierra.\n\nSu estado se ve en la página HYD del ECAM.","keyIdea":"El RAT solo se guarda con el avión en tierra."}],"test":[{"id":"hid-3-t1","type":"mcq","question":"¿Qué condición provoca el despliegue automático del RAT (Ram Air Turbine)?","options":["La pérdida de un solo generador principal","Pérdida simultánea de AC BUS 1 y AC BUS 2","La falla aislada del motor 1, con el motor 2 operativo","Una caída de presión en el sistema azul por debajo de 1500 PSI"],"correct":1,"explanation":"El RAT se despliega automáticamente si se pierden simultáneamente AC BUS 1 y AC BUS 2.","taughtIn":["hid-3-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:7phi8k"}},{"id":"hid-3-t2","type":"mcq","question":"¿Cuándo se puede guardar (stow) el RAT una vez desplegado?","options":["En vuelo, sin restricción","Solo en tierra","Nunca, una vez desplegado","Solo con motores parados"],"correct":1,"explanation":"Una vez desplegado, el RAT solo se puede guardar (stow) con el avión en tierra; en vuelo se queda afuera.","taughtIn":["hid-3-c5"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:11h3o6r"}},{"id":"hid-3-t3","type":"mcq","question":"¿Puede la tripulación extender el RAT manualmente en cualquier momento?","options":["No, solo se despliega de forma automática","Sí, presionando el RAT MAN ON pushbutton","Solo en tierra, antes del despegue","Solo si el APU está en marcha"],"correct":1,"explanation":"Además del despliegue automático ante la pérdida de ambos AC BUS, la tripulación tiene la opción de desplegar el RAT manualmente en cualquier momento del vuelo si lo considera necesario, presionando este pushbutton dedicado.","taughtIn":["hid-3-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:wph1oe"}},{"id":"hid-3-t4","type":"mcq","question":"¿Qué interpretación es correcta si la BLUE electric pump está en lógica automática y hay al menos un motor en marcha?","options":["La bomba Blue puede operar automáticamente","La bomba permanece apagada hasta seleccionar OVRD","La PTU la hace girar desde el sistema Green","El RAT debe estar desplegado para alimentarla"],"correct":0,"explanation":"El Blue system tiene una electric pump como fuente normal. Su operación automática está ligada a la condición de motores/energía disponible; el OVRD existe principalmente para necesidades de mantenimiento en tierra.","taughtIn":["hid-3-c1"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1elgumc"}},{"id":"hid-3-t5","type":"mcq","question":"¿Para qué sirve el BLUE PUMP OVRD pb sw del panel de mantenimiento?","options":["Para ordenar el stow manual del RAT después de una prueba en tierra","Para encender la Blue electric pump en tierra si HYD ELEC PUMP está en AUTO","Para ejecutar una prueba automática de la PTU durante el segundo engine start","Para cerrar una fire shutoff valve dedicada al Blue hydraulic system"],"correct":1,"explanation":"Es un interruptor de mantenimiento pensado para forzar la bomba eléctrica azul a encenderse en tierra (por ejemplo, para pruebas de superficies de control), siempre que el pushbutton normal de la bomba en el panel HYD de cabina esté en AUTO.","taughtIn":["hid-3-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1k7npkt"}}]},{"id":"hid-4","subject":"hidraulico","order":4,"kind":"lesson","level":2,"ident":"YEL","title":"El Yellow en tierra y las cargo doors","goal":"Explicar cómo se usa el Yellow en tierra y qué pasa al operar las cargo doors.","intro":"Hoy bajamos a la rampa: el Yellow en tierra y las cargo doors.","minutes":5,"cards":[{"id":"hid-4-c1","title":"Tres bombas propias","body":"El Yellow tiene tres bombas propias, sin contar la PTU: la bomba del motor 2, una bomba eléctrica y una hand pump.\n\nCon los motores apagados, la bomba eléctrica permite usar el Yellow en tierra.","diagram":{"alt":"El Yellow en tierra: la bomba eléctrica y la hand pump alimentan la cargo door, y la PTU queda inhibida.","src":"assets/estaciones/diagramas/hid-yellow-tierra.svg"},"keyIdea":"Yellow: ENG 2 pump, elec pump y hand pump."},{"id":"hid-4-c2","title":"La bomba eléctrica se enciende sola","body":"La Yellow elec pump se puede encender con el YELLOW ELEC PUMP pb. Además, **se enciende sola** cuando alguien mueve el selector manual de una cargo door a OPEN o CLOSE.\n\nMientras tanto, las demás funciones del Yellow quedan inhibidas, salvo el alternate braking y el reverser del motor 2.","keyIdea":"Mover el selector de una cargo door enciende sola la Yellow elec pump."},{"id":"hid-4-c3","title":"Sin electricidad: la hand pump","body":"Si no hay energía eléctrica, la tripulación puede presurizar el Yellow con la **hand pump** para abrir o cerrar las cargo doors.\n\nEl RAT, la PTU y el acumulador de frenos no sirven para esto: el RAT es del Blue, la PTU necesitaría presión en el Green y el acumulador de frenos es para los frenos.","keyIdea":"Sin electricidad, las cargo doors se operan con la hand pump del Yellow."},{"id":"hid-4-c4","title":"40 segundos sin PTU","body":"Mientras se usa la hand pump de la cargo door, y durante **40 s** después, la PTU queda inhibida.\n\nAsí el Green queda aislado de esa operación: el Yellow trabaja solo para la puerta.","example":"Por eso, si se arranca el último motor antes de que pasen 40 s desde el fin de la operación de las cargo doors, puede aparecer la alerta PTU FAULT.","keyIdea":"La PTU queda inhibida durante el uso de la hand pump de la cargo door y 40 s después."}],"test":[{"id":"hid-4-t1","type":"mcq","question":"¿Qué permite operar las puertas de carga (cargo doors) cuando no hay energía eléctrica disponible?","options":["La PTU, activada automáticamente en tierra","La bomba manual (hand pump) del sistema amarillo","El acumulador del sistema verde","La batería de emergencia conectada al motor eléctrico de la puerta"],"correct":1,"explanation":"Para operaciones en tierra sin energía eléctrica externa conectada, el sistema amarillo puede presurizarse manualmente con una bomba de mano, permitiendo a la tripulación de rampa abrir o cerrar las bodegas de carga sin depender de electricidad.","taughtIn":["hid-4-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:dyurw7"}},{"id":"hid-4-t2","type":"mcq","question":"¿Qué activa automáticamente la YELLOW ELEC PUMP?","options":["La selección de landing gear DOWN durante una extensión normal","El movimiento del selector manual de una cargo door a OPEN o CLOSE","La selección de flaps 1 cuando el avión inicia la carrera de despegue","La pérdida de AC BUS 1 con el sistema Yellow todavía presurizado"],"correct":1,"explanation":"La bomba eléctrica amarilla existe en parte para dar presión hidráulica al operar las puertas de carga en tierra sin depender de los motores. Por eso el sistema la enciende automáticamente en el momento exacto en que alguien mueve la palanca de operación manual de esas puertas.","taughtIn":["hid-4-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:ytp0xh"}},{"id":"hid-4-t3","type":"mcq","question":"Con ambos motores parados y sin electrical power, ¿qué medio permite todavía accionar hidráulicamente una cargo door?","options":["La hand pump del sistema Yellow","El RAT conectado al Blue system","La PTU impulsada desde el Green reservoir","El brake accumulator conectado al Yellow manifold"],"correct":0,"explanation":"Las cargo doors disponen de una hand pump asociada al Yellow system, de modo que pueden operarse sin depender de energía eléctrica normal. El RAT y el brake accumulator cumplen funciones diferentes.","taughtIn":["hid-4-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1xoimq6"}},{"id":"hid-4-t4","type":"mcq","question":"Durante apertura de una cargo door con la hand pump, ¿por qué se inhibe temporalmente la PTU?","options":["Para aislar Green de la demanda hidráulica de la cargo door","Para forzar que el sistema Blue alimente los actuadores de la puerta","Para despresurizar el reservorio Yellow antes de abrir la puerta","Para mantener al RAT como fuente hidráulica durante el ciclo"],"correct":0,"explanation":"La cargo door usa el Yellow. Mientras se opera con la hand pump, y durante 40 s después, la PTU queda inhibida: así el Green queda aislado de esa demanda y el Yellow trabaja solo para la puerta.","taughtIn":["hid-4-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:dhos2p"}},{"id":"hid-4-t5","type":"mcq","question":"Después de usar la hand pump de la cargo door, ¿cuánto tiempo permanece inhibida la PTU?","options":["40 s","10 s","2 min","90 s"],"correct":0,"explanation":"La PTU permanece inhibida mientras se usa la hand pump de la cargo door y durante 40 s después de usarla.","taughtIn":["hid-4-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:152269q"}}]},{"id":"hid-5","subject":"hidraulico","order":5,"kind":"lesson","level":2,"ident":"RSV","title":"Reservorios, acumuladores y priority valves","goal":"Explicar cómo el sistema protege su presión: reservorios presurizados, acumuladores y priority valves.","intro":"Hoy, las piezas que cuidan la presión del sistema.","minutes":5,"cards":[{"id":"hid-5-c1","title":"Reservorios con aire","body":"Cada reservorio está presurizado con aire. Normalmente lo hace el **HP bleed air del motor 1**; si esa presión es muy baja, el sistema toma aire del crossbleed duct.\n\n¿Para qué? Para que el fluido llegue con presión a la entrada de las bombas y no caviten, es decir, que no se formen burbujas en la entrada de la bomba.\n\nOjo: el reservorio no está a 3000 PSI. Su presión de aire es baja; los 3000 PSI los genera la bomba.","diagram":{"alt":"Un sistema hidráulico: reservorio presurizado con aire de bleed, bomba, acumulador y priority valve antes de los grandes consumidores.","src":"assets/estaciones/diagramas/hid-componentes.svg"},"keyIdea":"El aire de bleed presuriza los reservorios para que las bombas no caviten."},{"id":"hid-5-c2","title":"El acumulador","body":"Cada sistema tiene un **acumulador**, un depósito con fluido a presión. Cuando un actuador pide mucho caudal de golpe, el acumulador lo entrega al instante y la presión se mantiene estable.\n\nEs una reserva limitada de energía hidráulica: cubre demandas transitorias, pero no reemplaza a una bomba.","example":"Es como el estanque hidroneumático de una casa: si abres varias llaves a la vez, el agua sigue saliendo con presión mientras la bomba reacciona.","keyIdea":"El acumulador mantiene la presión estable y guarda una reserva limitada."},{"id":"hid-5-c3","title":"Las priority valves","body":"Si la presión de un sistema baja, las **priority valves** cortan la hidráulica a los usuarios de gran consumo, como el tren de aterrizaje y los flaps y slats.\n\nAsí la presión que queda se guarda para lo esencial: los flight controls.","keyIdea":"Con baja presión, las priority valves cortan a los grandes consumidores para proteger los flight controls."}],"test":[{"id":"hid-5-t1","type":"mcq","question":"¿Cuál es la función del acumulador en cada sistema hidráulico?","options":["Filtrar partículas metálicas del fluido","Mantener presión y cubrir demandas transitorias","Enfriar el fluido antes de que entre al reservorio","Detectar fugas internas del sistema"],"correct":1,"explanation":"El acumulador funciona como un 'amortiguador' de presión: cuando un usuario hidráulico exige un pico de caudal repentino (por ejemplo, mover una superficie de control con fuerza), el acumulador entrega ese extra al instante sin que la presión del sistema caiga bruscamente.","taughtIn":["hid-5-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1rl7xn"}},{"id":"hid-5-t2","type":"mcq","question":"¿Qué hacen las válvulas de prioridad (priority valves)?","options":["Aíslan usuarios de alta demanda cuando baja la presión","Regulan la temperatura del fluido en el reservorio","Distribuyen el fluido por igual entre todos los usuarios","Aíslan el sistema afectado por una leak measurement valve"],"correct":0,"explanation":"Ante una caída de presión, no todos los sistemas alimentados por ese circuito son igual de críticos. Las válvulas de prioridad cortan primero a los consumidores de alta demanda (como el tren de aterrizaje) para reservar la presión disponible a los sistemas esenciales, como los controles de vuelo.","taughtIn":["hid-5-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1cc2nae"}},{"id":"hid-5-t3","type":"mcq","question":"¿Qué presuriza normalmente los reservorios hidráulicos?","options":["Nitrógeno almacenado en botellas de alta presión","Aire HP de sangrado (bleed air) del motor 1","La propia bomba eléctrica azul","El compresor del pack de aire acondicionado"],"correct":1,"explanation":"Los reservorios necesitan estar presurizados con aire para asegurar que el fluido llegue bien a las bombas sin cavitar. Esa presión de aire viene normalmente del sangrado del motor 1; si esa fuente es insuficiente, el sistema toma aire del ducto de crossbleed como respaldo.","taughtIn":["hid-5-c1"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1gyi4dl"}},{"id":"hid-5-t4","type":"mcq","question":"Si una demanda importante hace caer la presión de un sistema hidráulico, ¿qué objetivo tienen las priority valves?","options":["Preservar presión para los consumidores esenciales","Transferir fluido entre reservorios hasta igualar cantidades","Aumentar la presión nominal por encima de 3000 psi","Cerrar todas las flight controls para priorizar frenos"],"correct":0,"explanation":"Las priority valves administran una caída de presión: aíslan consumidores de menor prioridad para conservar la capacidad hidráulica de los servicios esenciales. No mezclan sistemas ni aumentan la presión nominal.","taughtIn":["hid-5-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1eeeise"}},{"id":"hid-5-t5","type":"mcq","question":"¿Qué ventaja aporta presurizar los hydraulic reservoirs con aire del sistema neumático?","options":["Asegurar alimentación positiva a las bombas y reducir riesgo de cavitación","Permitir que un reservoir alimente directamente actuadores sin usar bombas","Mantener 3 000 psi en el reservoir aun con todas las bombas apagadas","Transferir automáticamente fluido entre Green, Blue y Yellow según demanda"],"correct":0,"explanation":"La presión del reservoir ayuda a que las bombas reciban fluido de forma positiva. La presión de trabajo de los actuadores la generan las bombas; el reservoir no está a la presión nominal del circuito.","taughtIn":["hid-5-c1"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:ebc069"}},{"id":"hid-5-t6","type":"mcq","question":"¿Qué aporta el hydraulic accumulator además de absorber pulsaciones de presión?","options":["Una reserva limitada de energía hidráulica","Una transferencia continua entre los tres reservorios","Una fuente permanente de 3000 psi sin bombas","La presurización neumática normal de los reservorios"],"correct":0,"explanation":"Un acumulador almacena energía hidráulica y suaviza variaciones de presión. Es una reserva limitada para transitorios; no sustituye indefinidamente a una bomba ni conecta los reservoirs.","taughtIn":["hid-5-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1ag6u9w"}}]},{"id":"hid-6","subject":"hidraulico","order":6,"kind":"lesson","level":3,"ident":"VLV","title":"Válvulas, filtros y la luz FAULT","goal":"Explicar las válvulas de corte y de medición, los filtros de las bombas y qué enciende el FAULT de una bomba de motor.","intro":"Última clase del hidráulico: válvulas, filtros y qué significa una luz FAULT.","minutes":5,"cards":[{"id":"hid-6-c1","title":"Fire shutoff valves","body":"El Green y el Yellow tienen una **fire shutoff valve** en la línea que va a su bomba de motor, antes de la bomba (upstream). La tripulación la cierra con el **ENG 1(2) FIRE pb**, y así deja de llegar fluido hidráulico al motor con fuego.\n\nEl Blue no tiene, porque no tiene bomba de motor.","diagram":{"alt":"Recorrido de un sistema con bomba de motor: fire shutoff valve antes de la bomba, case drain filter en la bomba y leak measurement valve antes de los primary flight controls.","src":"assets/estaciones/diagramas/hid-valvulas.svg"},"keyIdea":"Solo Green y Yellow tienen fire shutoff valve; se cierra con el ENG FIRE pb."},{"id":"hid-6-c2","title":"Leak measurement valves","body":"Cada sistema tiene una **leak measurement valve** antes (upstream) de los primary flight controls.\n\nMantenimiento las cierra con el LEAK MEASUREMENT VALVES pb del maintenance panel: así corta la hidráulica a los primary flight controls y puede medir las fugas de cada circuito.","keyIdea":"Las leak measurement valves aíslan los primary flight controls para medir fugas; se cierran desde el maintenance panel."},{"id":"hid-6-c3","title":"Filtros que avisan desgaste","body":"El fluido pasa por varios filtros que lo limpian.\n\nLos **case drain filters** de las bombas de motor y de la bomba eléctrica del Blue tienen un uso extra: mantenimiento los revisa buscando partículas metálicas, señal de que una bomba se está desgastando.","keyIdea":"Los case drain filters permiten detectar el desgaste de una bomba."},{"id":"hid-6-c4","title":"La luz FAULT del ENG PUMP pb","body":"La luz ámbar **FAULT** del ENG 1(2) PUMP pb, con su caution en el ECAM, se enciende por problemas del propio circuito hidráulico:\n- nivel bajo en el reservorio;\n- reservorio con sobretemperatura;\n- baja presión de aire en el reservorio;\n- baja presión de la bomba (inhibida en tierra con el motor detenido).\n\nAl seleccionar OFF la luz se apaga, salvo que sea una sobretemperatura.","keyIdea":"El FAULT avisa problemas del circuito hidráulico (reservorio o bomba), no eléctricos."}],"test":[{"id":"hid-6-t1","type":"mcq","question":"¿Qué sistemas tienen válvula de corte por fuego (fire shutoff valve) y cómo se cierra?","options":["Blue y Green; mediante el HYD overhead panel","Green y Yellow; mediante ENG 1(2) FIRE pb","Los tres sistemas; desde el maintenance panel","Solo Yellow; con una llave de mantenimiento"],"correct":1,"explanation":"Solo verde y amarillo tienen bombas accionadas directamente por los motores, así que son los únicos con una válvula de corte de fuego ligada a esos motores. El sistema azul, al no depender de un motor, no necesita esta protección. La tripulación corta el flujo de fluido hacia el motor en llamas simplemente presionando el pushbutton de fuego correspondiente.","taughtIn":["hid-6-c1"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:b04mx9"}},{"id":"hid-6-t2","type":"mcq","question":"¿Dónde están ubicadas las leak measurement valves y qué las cierra?","options":["Aguas abajo de primary flight controls; las cierra el ENG FIRE pushbutton","Aguas arriba de primary flight controls; las cierra un pushbutton de maintenance","En cada reservoir outlet; las cierra la tripulación desde el HYD overhead panel","En la línea de la PTU; cierran automáticamente cada vez que el avión está en vuelo"],"correct":1,"explanation":"Estas válvulas existen para que mantenimiento pueda aislar los controles de vuelo primarios del resto del sistema y así medir si hay una fuga interna en esa sección específica, sin afectar el resto del circuito hidráulico. Se controlan desde el panel de mantenimiento, no desde la cabina de vuelo en operación normal.","taughtIn":["hid-6-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1uwtf1u"}},{"id":"hid-6-t3","type":"mcq","question":"Si se cierra una leak measurement valve durante una prueba de fuga, ¿qué parte del sistema se busca aislar principalmente?","options":["Los primary flight controls, sin suministro hidráulico","El reservorio completo, con las bombas aún en marcha","La bomba accionada por motor, transfiriendo su demanda a la PTU","El circuito de frenos, que pasa a presión Green independiente"],"correct":0,"explanation":"Con el pushbutton LEAK MEASUREMENT VALVES en OFF, la válvula electrohidráulica correspondiente se cierra y corta el suministro hidráulico a los primary flight controls; la válvula está aguas arriba de ellos. Estas válvulas miden la fuga de cada circuito; en ON el suministro vuelve a ser el normal.","taughtIn":["hid-6-c2"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:wo7j9h"}},{"id":"hid-6-t4","type":"mcq","question":"¿Para qué sirven los case drain filters de las bombas de motor y la bomba eléctrica azul?","options":["Enfriar el fluido hidráulico antes de retornar al reservorio","Monitorear desgaste de bomba por partículas metálicas","Filtrar el aire de presurización del reservorio","Detectar fugas externas visibles en las líneas"],"correct":1,"explanation":"Estos filtros no cumplen una función de operación en vuelo, sino de diagnóstico: al inspeccionarlos, mantenimiento puede detectar partículas metálicas que indiquen desgaste interno de una bomba antes de que falle, de forma preventiva.","taughtIn":["hid-6-c3"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:1vdkb3a"}},{"id":"hid-6-t5","type":"mcq","question":"¿Cuál de las siguientes NO es una causa listada del FAULT light del ENG 1(2) PUMP pb?","options":["Nivel de reservorio bajo","Sobrecalentamiento del reservorio","Presión de la bomba baja con el motor en marcha","Falla del generador eléctrico AC 1"],"correct":3,"explanation":"El FAULT light de la bomba de motor está ligado exclusivamente a condiciones propias del circuito hidráulico de esa bomba (nivel, temperatura, presión de aire del reservorio, presión de salida de la bomba). Una falla eléctrica del generador AC 1 pertenece a un sistema completamente distinto y no enciende esta luz.","taughtIn":["hid-6-c4"],"source":{"bank":"fcom","system":"hydraulic","appId":"hydraulic:11yke7r"}}]},{"id":"hid-repaso","subject":"hidraulico","order":7,"kind":"review","level":3,"ident":"RHY","title":"Repaso del hidráulico","goal":"Comprobar que recuerdas todo el sistema, con preguntas planteadas de otra forma.","intro":"Repaso general: las mismas ideas, preguntadas de otra forma. Al final, explícame todo el sistema con tu voz.","minutes":5,"cards":[{"id":"hid-repaso-c1","title":"Todo el sistema en una mirada","body":"Antes de empezar, repasa el esquema: tres sistemas a 3000 PSI, la bomba normal de cada uno, sus respaldos y la PTU entre Green y Yellow.","diagram":{"alt":"Esquema de los tres sistemas hidráulicos con sus bombas, sus reservorios y la PTU entre Green y Yellow.","src":"assets/estaciones/diagramas/hid-arquitectura.svg"},"keyIdea":"Tres sistemas, su bomba normal, sus respaldos y la PTU."}],"test":[{"id":"hid-repaso-t1","type":"mcq","question":"HOW MANY PUMPS HAVE THE YELLOW SYSTEM TO PROVIDE PRESSURE (NOT COUNTING THE PTU)?","options":["1","2","3","4"],"correct":2,"explanation":"El sistema Yellow cuenta con tres bombas propias sin contar la PTU: una bomba accionada por el motor 2, una bomba eléctrica, y una bomba manual (hand pump) usada, entre otras cosas, para operar las puertas de carga.","taughtIn":["hid-4-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:vaq84q"}},{"id":"hid-repaso-t2","type":"mcq","question":"THE A-320'S THREE HYDRAULIC SYSTEMS ARE NORMALLY PRESSURIZED BY:","options":["TWO ENGINE DRIVEN PUMPS AND ONE ELECRECTRIC PUMP.","TWO ELECTRIC PUMPS AND ONE PTU.","TWO ELECTRIC PUMPS AND ONE ENGINE DRIVEN PUMP.","ONE ELECTRIC PUMP AND ONE ENGINE DRIVEN PUMP."],"correct":0,"explanation":"En condición normal, Green y Yellow se presurizan cada uno con su propia bomba accionada por motor (ENG 1 y ENG 2 respectivamente), mientras que Blue se presuriza con una bomba eléctrica; en conjunto, dos bombas accionadas por motor y una eléctrica.","taughtIn":["hid-1-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:jsgdff"}},{"id":"hid-repaso-t3","type":"mcq","question":"THE RAT PRESSURIZES THE BLUE HYDRAULIC SYSTEM TO APPROXIMATELY _____ PSI.","options":["1500","2500","3000"],"correct":1,"explanation":"El RAT presuriza el sistema azul a aproximadamente 2500 psi, un valor menor a la presión normal del sistema (3000 psi), reflejando la menor capacidad de la turbina eólica frente a una bomba accionada por motor o eléctrica.","taughtIn":["hid-1-c3","hid-3-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:yxp06k"}},{"id":"hid-repaso-t4","type":"mcq","question":"WITH THE AIRPLANE ON THE GROUND AND THE BLUE ELECTRIC PUMP SWITCH IN AUTO; THE BLUE PUMP WILL BE ENERGIZED WHEN:","options":["ONE ENGINE IS RUNNING.","THE BLUE PUMP OVRD SWITCH HAS BEEN PRESSED.","FIRST TWO STATEMENTS ARE CORRECT."],"correct":2,"explanation":"En tierra con el switch de la bomba eléctrica azul en AUTO, la bomba se energiza cuando al menos un motor está en marcha, o cuando se presiona el switch OVRD de la bomba azul, sin depender de otras condiciones.","taughtIn":["hid-3-c1","hid-3-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:f0bf7c"}},{"id":"hid-repaso-t5","type":"mcq","question":"FOR HYDRAULIC SYSTEM MALFUNCTIONS, WHEN WILL THE RAT DEPLOY?","options":["AUTOMATICALLY WITH THE FAILURE OF BOTH THE GREEN AND BLUE HYDRAULIC SYSTEMS.","AUTOMATICALLY WITH THE FAILURE OF BOTH THE GREEN AND YELLOW HYDRAULIC SYSTEMS.","ONLY WHEN THE GUARDED RAT MAN ON PUSH BUTTON IS SELECTED BY THE CREW.","WHEN AIRSPEED DROPS BELOW 100 KNOTS WITH THE GEAR UP."],"correct":2,"explanation":"Ante una falla puramente hidráulica, el RAT no se despliega automáticamente: requiere que la tripulación seleccione manualmente el pushbutton guardado RAT MAN ON. El despliegue automático del RAT está ligado a condiciones de emergencia eléctrica, no a la sola pérdida de sistemas hidráulicos.","taughtIn":["hid-3-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:d56i8j"}},{"id":"hid-repaso-t6","type":"oral","question":"Observa el diagrama del sistema hidráulico y explica su arquitectura: cuántos sistemas hay, qué presuriza a cada uno, y qué respaldos existen.","image":{"alt":"Esquema de los tres sistemas hidráulicos del A320.","src":"assets/estaciones/diagramas/hid-arquitectura.svg"},"reference":"Hay tres sistemas hidráulicos independientes que operan continuamente: verde, azul y amarillo, cada uno con su propio reservorio y sin transferencia de fluido entre ellos, a 3000 PSI normalmente (2500 PSI si lo alimenta el RAT). El verde lo presuriza una bomba del motor 1. El amarillo lo presuriza una bomba del motor 2, y también una bomba eléctrica que permite usarlo en tierra con los motores apagados. El azul lo presuriza normalmente una bomba eléctrica, y el RAT lo presuriza automáticamente si se pierden AC BUS 1 y AC BUS 2 (también se puede desplegar manualmente desde el panel superior). La PTU conecta el verde y el amarillo y actúa automáticamente cuando la diferencia de presión entre ambos supera 500 PSI, lo que también permite presurizar el verde en tierra sin motores. Cada sistema tiene un acumulador para cubrir demandas transitorias, y el verde y el amarillo tienen una válvula de corte de fuego en la línea de su bomba de motor, operada por el pushbutton ENG FIRE.","concepts":[{"label":"Tres sistemas independientes (verde/azul/amarillo), sin transferencia de fluido entre ellos","weight":2,"required":true,"accepted":["tres sistemas","verde","azul","amarillo","no se transfiere","sin transferencia","cada uno independiente","tres circuitos","no hay transferencia de fluido"]},{"label":"Verde: bomba del motor 1","weight":2,"required":true,"accepted":["verde","motor 1","eng 1","bomba del motor 1","engine 1"]},{"label":"Amarillo: bomba del motor 2 y bomba eléctrica (permite operar en tierra)","weight":2,"required":true,"accepted":["amarillo","motor 2","eng 2","bomba electrica","electric pump","en tierra","motores apagados"]},{"label":"Azul: bomba eléctrica normalmente, RAT en emergencia","weight":2,"required":true,"accepted":["azul","bomba electrica","rat","ram air turbine","en emergencia"]},{"label":"PTU conecta verde y amarillo (~500 PSI)","weight":2,"accepted":["ptu","power transfer unit","500 psi","transferencia de potencia","conecta verde y amarillo"]},{"label":"Acumuladores cubren demandas transitorias","weight":1,"accepted":["acumulador","acumuladores","demandas transitorias","mantener la presion"]},{"label":"Fire shutoff valves en las bombas de motor","weight":1,"accepted":["fire shutoff","valvula de corte de fuego","eng fire","corte de fuego"]},{"label":"Presión normal 3000 PSI","weight":1,"accepted":["3000 psi","2500 psi"]}],"criticalErrors":[{"accepted":["se puede transferir fluido entre sistemas","comparten el mismo fluido","estan interconectados directamente","es un solo sistema hidraulico"],"penalty":3,"feedback":"Los tres sistemas son independientes: el fluido nunca se transfiere entre ellos (la PTU transfiere potencia hidráulica de un sistema a otro, no fluido)."}],"taughtIn":["hid-1-c2","hid-1-c3","hid-1-c4","hid-1-c5","hid-2-c3","hid-2-c4","hid-3-c4","hid-5-c2","hid-6-c1"],"source":{"bank":"oral","id":"ov_hyd_arch"}}]}]}],"route":{"zones":[{"id":"pista","title":"Pista de salida","bg":"assets/estaciones/imagenes/mapa-1-aeropuerto-salida.webp"},{"id":"nubes","title":"Nubes","bg":"assets/estaciones/imagenes/mapa-2-nubes.webp"},{"id":"crucero","title":"Crucero","bg":"assets/estaciones/imagenes/mapa-3-crucero.webp"},{"id":"mal-tiempo","title":"Mal tiempo","bg":"assets/estaciones/imagenes/mapa-4-mal-tiempo.webp"},{"id":"tormenta","title":"Tormenta","bg":"assets/estaciones/imagenes/mapa-5-tormentas.webp"},{"id":"descenso","title":"Descenso","bg":"assets/estaciones/imagenes/mapa-6-atardecer.webp"},{"id":"llegada","title":"Pista de llegada","bg":"assets/estaciones/imagenes/mapa-7-aeropuerto-llegada.webp"}],"missions":[{"n":1,"id":"hid-1","subject":"hidraulico","title":"Tres sistemas independientes","kind":"lesson","level":1,"minutes":6,"zone":"pista","unlockAfter":null},{"n":2,"id":"ele-1","subject":"electrico","title":"Las fuentes de energía","kind":"lesson","level":1,"minutes":5,"zone":"pista","unlockAfter":"hid-1"},{"n":3,"id":"hid-2","subject":"hidraulico","title":"La PTU","kind":"lesson","level":1,"minutes":5,"zone":"pista","unlockAfter":"ele-1"},{"n":4,"id":"ele-2","subject":"electrico","title":"Quién alimenta a quién","kind":"lesson","level":1,"minutes":5,"zone":"nubes","unlockAfter":"hid-2"},{"n":5,"id":"ele-3","subject":"electrico","title":"Prioridades y el BUS TIE","kind":"lesson","level":1,"minutes":7,"zone":"nubes","unlockAfter":"ele-2"},{"n":6,"id":"hid-3","subject":"hidraulico","title":"El Blue y el RAT","kind":"lesson","level":2,"minutes":6,"zone":"crucero","unlockAfter":"ele-3"},{"n":7,"id":"ele-4","subject":"electrico","title":"External power, APU GEN y galleys","kind":"lesson","level":2,"minutes":6,"zone":"crucero","unlockAfter":"hid-3"},{"n":8,"id":"hid-4","subject":"hidraulico","title":"El Yellow en tierra y las cargo doors","kind":"lesson","level":2,"minutes":5,"zone":"crucero","unlockAfter":"ele-4"},{"n":9,"id":"ele-5","subject":"electrico","title":"El IDG y la falla de un generador","kind":"lesson","level":2,"minutes":6,"zone":"mal-tiempo","unlockAfter":"hid-4"},{"n":10,"id":"hid-5","subject":"hidraulico","title":"Reservorios, acumuladores y priority valves","kind":"lesson","level":2,"minutes":5,"zone":"mal-tiempo","unlockAfter":"ele-5"},{"n":11,"id":"ele-6","subject":"electrico","title":"Las baterías","kind":"lesson","level":2,"minutes":6,"zone":"mal-tiempo","unlockAfter":"hid-5"},{"n":12,"id":"hid-6","subject":"hidraulico","title":"Válvulas, filtros y la luz FAULT","kind":"lesson","level":3,"minutes":5,"zone":"tormenta","unlockAfter":"ele-6"},{"n":13,"id":"ele-7","subject":"electrico","title":"Cuándo se conectan las baterías","kind":"lesson","level":3,"minutes":5,"zone":"tormenta","unlockAfter":"hid-6"},{"n":14,"id":"ele-8","subject":"electrico","title":"Fallas parciales: TR, AC BUS 1 y humo","kind":"lesson","level":3,"minutes":6,"zone":"tormenta","unlockAfter":"ele-7"},{"n":15,"id":"ele-9","subject":"electrico","title":"Emergencia: el RAT y el EMER GEN","kind":"lesson","level":3,"minutes":6,"zone":"tormenta","unlockAfter":"ele-8"},{"n":16,"id":"ele-10","subject":"electrico","title":"Solo baterías: el static inverter","kind":"lesson","level":3,"minutes":5,"zone":"tormenta","unlockAfter":"ele-9"},{"n":17,"id":"hid-repaso","subject":"hidraulico","title":"Repaso del hidráulico","kind":"review","level":3,"minutes":5,"zone":"descenso","unlockAfter":"ele-10"},{"n":18,"id":"ele-repaso","subject":"electrico","title":"Repaso del eléctrico","kind":"review","level":3,"minutes":7,"zone":"descenso","unlockAfter":"hid-repaso"}],"plane":"assets/estaciones/imagenes/mapa-avion.webp"}};
